(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-bandwidth-efficient-adaptive-mixture-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-1\">一 · 现场：一个在线推理集群的带宽账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-2\">二 · 旧方案一：全量专家权重读取与分组 GEMM 的天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-3\">三 · 旧方案二：量化与剪枝为何没打中这条路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-4\">四 · 痛点收束：三个必须同时满足的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-5\">五 · 一个预填批次的对照账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-6\">六 · 为什么这条路径值得在 Blackwell 上单独设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-7\">七 · 负载形态先于方案：输入长度、并发与批的三条约束线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-8\">八 · SLO 与长尾：回退率是尾延迟的直接输入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-9\">九 · 方案反过来限制负载：批大小与并发的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-10\">十 · 预填与解码的负载分裂：两套口径不能混用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-11\">十一 · 长尾专家与命中分布：回退判定的粒度问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-12\">十二 · 可核查的测量清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-13\">十三 · 低秩路径的 kernel 形状：从分组 GEMM 到补偿 GEMM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-14\">十四 · 数据类型：FP16/BF16 基线、FP8 与 NVFP4 的位宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-15\">十五 · 累加精度与误差传播：残差判定的数值地基</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM、2-SM MMA 与第五代 Tensor Core</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-17\">十七 · 算子编排与系统代价：分流、尖峰与容量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-18\">十八 · 显存账本的三层结构：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-19\">十九 · 低秩因子的常驻代价与回退的带宽尖峰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-20\">二十 · 分页、压缩、复用、卸载：四类手段各自打在哪本账上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-21\">二十一 · 带宽瓶颈的位置：HBM3e 容量与读取量的对账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-22\">二十二 · 残差判定与调度器的联动：把阈值变成容量旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-23\">二十三 · 与量化、KV 策略共存的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-24\">二十四 · 连续批处理在低秩补偿路径上的分流结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-25\">二十五 · Chunked prefill 与回退判定的时序耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-26\">二十六 · 优先级、抢占与回退率的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-27\">二十七 · 分离式预填/解码下的回退归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-28\">二十八 · 尾延迟的压制手段与带宽尖峰的观测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-29\">二十九 · 切分维度与低秩分支的落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-30\">三十 · NVLink 5 与 NVSwitch：All-to-All 的物理上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-31\">三十一 · NIXL 与分离式部署下的因子搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-32\">三十二 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-33\">三十三 · 拓扑与阈值的联动调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-34\">三十四 · 监控指标与失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-35\">三十五 · 并行拓扑下的通信边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-36\">三十六 · 精度塌陷：从残差判定到回退路径的失效链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-37\">三十七 · OOM：常驻低秩因子与 KV cache 的显存争用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-38\">三十八 · 批抖动与尾延迟：回退率作为批内随机变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-39\">三十九 · 静默降级：监控指标的设计与陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-40\">四十 · 定位与回滚：从指标到动作的路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-41\">四十一 · 失败模式与容量规划的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-42\">四十二 · 基准口径的骨架：先钉死模型与硬件档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-43\">四十三 · batch 与并发：两种分母不能混用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-44\">四十四 · 指标族：TTFT、TPOT、吞吐、显存、功耗各自的口径陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-45\">四十五 · 数字怎么读：把“提升”拆成可归因的因子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-46\">四十六 · 不可比清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-47\">四十七 · 迁移到非 MoE 结构：低秩补偿失去路由这个抓手</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-48\">四十八 · 领域迁移：长上下文、多模态与低延迟场景的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-49\">四十九 · 规模上限：专家并行度、All-to-All 与常驻显存的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-50\">五十 · 量化共存与数值边界：低秩因子与 NVFP4/FP8 的相互影响</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-51\">五十一 · 不适用清单与迁移检查项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-52\">五十二 · 迁移边界：什么模型吃得下这套方案，什么拓扑会把它吃掉</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入批调度器，按 token 长度与并发形成批次，预填阶段计算路由…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">路由结果与门控系数写入低秩补偿分支，按专家索引读取低秩因子，分组 GE…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对低秩近似残差超过阈值的 token，标记为需回退，触发对应专家的完整…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">专家并行下通过 All-to-All 交换低秩中间激活与门控系数，按拓…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码阶段复用已缓存的低秩因子与 KV cache，按 SLO 调整批大…</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出聚合门控加权结果，记录回退率与专家命中分布，供容量规划与并行拓扑调…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-1\">一 · 现场：一个在线推理集群的带宽账本</h3>\n<p>把镜头拉到一条真实的服务链路上：某在线助手后端挂着 8 卡 NVL72 单机柜，模型是 64 专家、top-2 路由的 MoE，权重按 NVFP4 存放，KV cache 用常规分页方案。请求以变长流式方式到达，批调度器把 32 条并发请求凑成一个预填批次，每批约 4k token。路由层为每个 token 选出 2 个专家并给出门控系数，随后分组 GEMM 按专家索引把 token 分桶，逐专家读取权重做矩阵乘。问题出在这一步：4k token × 2 专家 = 8k 次专家命中，若专家分布均匀，平均每个专家被命中约 125 次，但 MoE 的路由天然偏斜，头部专家可能被命中上千次，尾部专家只被命中个位数。分组 GEMM 的权重读取量随激活专家数线性增长，而每个专家的权重矩阵在 NVFP4 下仍是数十 MB 量级——一次预填批次要把几十个专家的权重从 HBM 搬到 SM，搬运量远超激活本身。</p>\n<p>Blackwell 档位给了 tcgen05 MMA、TMEM 与 NVFP4/FP8 的算力，单看 FLOPS 余量充足；但推理的瓶颈已经从算力转向显存带宽与专家权重搬运。B200 的 HBM 带宽是有限资源，分组 GEMM 的权重读取与 KV cache 的读写共享同一条通道。当批大小上调以提升吞吐时，专家命中集合变大，权重读取量随之上升，带宽被权重搬运吃掉，解码阶段的 KV cache 读取被挤压，尾延迟抬升。这就是“算力没用满、带宽先见底”的典型现场：SLO 要求 P99 首 token 延迟稳定，而调度器发现扩容 GPU 并不能线性提升吞吐，因为每 token 触发的专家权重带宽是硬约束。</p>\n<p>专家并行把这个问题放大。64 专家切到 8 卡上，每卡常驻 8 个专家；一个 token 的 top-2 专家若落在不同卡上，就要经 All-to-All 交换激活。跨卡激活体积与命中专家数成正比，NVL72 的 NVLink 5 虽快，但 All-to-All 的同步开销与激活体积叠加，在预填大批次下形成可观测的通信墙。更麻烦的是路由偏斜：热点专家所在卡成为带宽与通信的集中点，负载不均导致部分卡先饱和，整体吞吐被最慢的那张卡钉住。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-2\">二 · 旧方案一：全量专家权重读取与分组 GEMM 的天花板</h3>\n<p>论文之前的主流做法是“路由即读权重”：top-k 选中哪些专家，就把这些专家的完整权重读进来做分组 GEMM。实现上通常按专家索引对 token 排序分桶，每个专家一个 GEMM 实例，权重从 HBM 经 L2 流入 SMEM 再进 Tensor Core。这条路径的代价可以用一个简单的带宽账本表达：设批内 token 数为 $B$、路由 top-k 为 $k$、专家权重单专家字节数为 $S_w$、命中专家集合大小为 $E_h$，则单批次权重读取量约为</p>\n<div class=\"formula\">$$V_{\\text{weight}} \\approx E_h \\cdot S_w,\\qquad E_h \\le \\min(N_e,\\, B\\cdot k)$$</div>\n<p>其中 $N_e$ 是专家总数。关键在于 $E_h$ 随批大小增长：批越大，token 覆盖的专家越多，权重读取量越接近全专家集合。这意味着吞吐与带宽之间不是线性关系，而是批大小越过某个点后，权重搬运成为主导项，分组 GEMM 的有效算力利用率下降。对 64 专家、top-2 的配置，一个 4k token 的预填批次几乎必然触发大部分专家，权重读取量接近“全专家扫描”，低秩补偿要解决的正是这个 $E_h \\cdot S_w$ 项。</p>\n<p>这条路径还有两个隐性代价。其一是权重读取的突发性：分组 GEMM 按专家串行或分组执行，权重读取在时间上集中，形成带宽尖峰，与 KV cache 的周期性读写叠加后，尾延迟抖动明显。其二是专家并行的 All-to-All：激活需要按目标专家重排后跨卡发送，跨卡体积与 $B \\cdot k$ 成正比，热点专家使某些链路的发送量远超均值。工程上常见的缓解手段是提高批大小摊薄权重读取、用专家亲和调度减少跨卡跳数、或对热点专家做复制，但这些手段都在“读全量权重”这个前提内做优化，天花板由 $S_w$ 决定，无法把每 token 的权重带宽降一个量级。</p>\n<p>具体例子：一个解码步 batch=256、top-2，命中约 40 个不同专家，若单专家 NVFP4 权重为 32MB，则该步权重读取约 1.28GB；在 B200 的带宽量级下，这一步的权重搬运时间与计算时间可比，解码的 token 间延迟被权重读取主导。把 batch 提到 512，命中专家数上升，权重读取量继续增长，吞吐提升被带宽吃掉——这就是“非改不可”的量化理由。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-3\">三 · 旧方案二：量化与剪枝为何没打中这条路径</h3>\n<p>NVFP4/FP8 量化把 $S_w$ 压小，是对上述账本最直接的攻击：位宽减半，权重读取量近似减半。但量化只改变单位字节，不改变“每 token 触发多少专家权重”这个结构项。只要路由仍然要求读取被选中专家的完整矩阵，$E_h$ 的增长逻辑不变，量化带来的收益是常数因子，而非量级变化。更现实的是，低比特权重的解压与缩放因子读取本身要占带宽，NVFP4 的块缩放元数据在分组 GEMM 中引入额外读取，量化收益被部分抵消。量化是必要的底座，但它单独无法把 MoE 推理从带宽约束里拉出来。</p>\n<p>剪枝类方案走另一条路：按专家重要性剪掉尾部专家或压缩专家内部结构。问题在于 MoE 的表达能力恰恰依赖专家分工，剪掉尾部专家会改变路由分布，长尾 token 的质量下降；而结构化剪枝若作用在专家权重内部，等于改变了专家函数本身，需要重新对齐路由与权重，推理侧无法单独完成。对在线服务而言，剪枝是不可逆的模型改动，不能作为运行时旋钮；而带宽约束是随负载波动的，需要的是可调的回退机制，而不是一次性削减。</p>\n<p>还有一类做法是缓存热点专家权重到片上或近端存储，减少 HBM 读取。SMEM 容量有限，一个专家的权重矩阵放不进 SMEM；L2 能缓存部分热点专家，但 L2 容量与 KV cache 争用，且缓存命中率随路由偏斜变化，尾延迟不可控。这些方案共同的问题是：它们都在“读完整专家权重”的框架内做局部优化，没有改变每 token 的权重读取路径本身。论文的切入点因此落在路由之后的权重读取路径上——用低秩因子近似专家贡献，把“全量读取”换成“低秩因子读取加少量补偿”。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-4\">四 · 痛点收束：三个必须同时满足的约束</h3>\n<p>把现场与旧方案的代价收束成三条约束。第一条是带宽约束：每 token 的专家权重读取量必须与批大小解耦，否则吞吐提升必然撞上带宽墙。第二条是精度约束：MoE 的路由表达能力不能因压缩而退化，长尾专家的近似误差要可控，否则在线服务质量不可接受。第三条是拓扑约束：专家并行下的 All-to-All 激活体积要随压缩同步下降，否则跨卡通信成为新的瓶颈，压缩只省了 HBM 却省不了网络。</p>\n<p>这三条约束互相牵制。要降带宽就得少读权重，少读权重就引入近似误差，误差要靠回退补偿，回退又制造带宽尖峰；要降 All-to-All 就得压缩跨卡激活，压缩激活要求低秩中间表示与专家切分对齐，切分带来同步开销。旧方案各自只解一条：量化解带宽的常数项、剪枝解专家数、缓存解热点，但没有一个方案同时把三条约束纳入一个可调旋钮。论文的低秩补偿分支正是把这个旋钮显式化：路由给出 top-k 与门控权重后，先读低秩因子 $U_e V_e^{\\top}$ 聚合贡献，残差超过阈值 $\\tau$ 的 token 才回退读完整 $W_e$。带宽账本从 $E_h \\cdot S_w$ 变为 $E_h \\cdot S_{\\text{lr}} + r \\cdot E_h \\cdot S_w$，其中 $S_{\\text{lr}}$ 是低秩因子字节数、$r$ 是回退比例；只要 $S_{\\text{lr}} \\ll S_w$ 且 $r$ 受控，每 token 权重带宽就降一个量级。</p>\n<p>工程判断在这里变得具体：$\\tau$ 是带宽与精度的显式旋钮，$\\tau$ 越低回退越多、带宽节省越少但近似误差越小；低秩因子的秩决定 $S_{\\text{lr}}$，秩越小节省越明显但近似误差上升；低秩因子常驻显存是容量代价，专家数越多、秩越大，常驻占用越高，需与 KV cache 和批大小共同规划显存预算。这三者在部署时构成一个容量规划三角，任何一个维度拉满都会侵蚀另外两个的收益。在线服务场景下，调度器需要监控回退率、专家命中分布、带宽占用与尾延迟，回退率升高时联动调整阈值或并行拓扑——这正是旧方案缺失的运行时反馈回路。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-5\">五 · 一个预填批次的对照账本</h3>\n<p>用同一个 4k token 预填批次做对照。旧路径：命中约 50 个专家，单专家 NVFP4 权重 32MB，权重读取约 1.6GB，分组 GEMM 的权重搬运时间与 MMA 时间同量级，带宽尖峰出现在专家串行执行的窗口内。低秩路径：低秩因子按专家常驻，设秩使单专家因子字节数为 $S_{\\text{lr}}$，则低秩聚合阶段读取约 $50 \\cdot S_{\\text{lr}}$；残差判定后，假设回退比例为 $r$，补偿阶段再读 $r \\cdot 50 \\cdot S_w$。若 $S_{\\text{lr}}$ 远小于 $S_w$ 且 $r$ 较小，总读取量显著低于 1.6GB，且读取在时间上被分成低秩聚合与稀疏补偿两段，尖峰被摊平。代价是残差判定本身要算 $\\|\\mathrm{res}_e\\|$，这需要低秩近似结果与完整结果之差——工程上通常用低秩路径的输出与门控加权后的统计量做近似判定，判定开销是少量额外计算与分支。</p>\n<p>专家并行下的对照更关键。旧路径 All-to-All 交换的是全量激活，体积与 $B \\cdot k$ 成正比；低秩路径只交换低秩中间激活与门控系数，跨卡体积按低秩维度缩减，NVL72 的链路压力下降。但切分带来同步成本：低秩因子要与专家权重同拓扑切分，回退时完整权重的读取仍按原拓扑发生，若回退集中在某张卡的热点专家上，该卡同时承担低秩聚合与补偿读取，成为新的集中点。调度器因此要把回退比例作为批调度的一个约束：尾延迟敏感场景限制回退比例，避免带宽尖峰破坏 SLO。</p>\n<p>解码阶段的账本不同：batch=256、top-2，命中约 40 专家，旧路径每步权重读取约 1.28GB；低秩路径复用常驻因子，低秩聚合读取量小，回退 token 稀疏触发补偿读取，单步带宽占用下降，token 间延迟的方差也随之下降。KV cache 策略不变，但低秩因子常驻显存与 KV cache 争用容量，专家数多、秩大时需压缩批大小或降低秩，这是部署时必须算清的显存预算项。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-6\">六 · 为什么这条路径值得在 Blackwell 上单独设计</h3>\n<p>Blackwell 的 tcgen05 MMA 与 TMEM 让分组 GEMM 的算力不再是瓶颈，TMEM 作为累加器减少了寄存器压力，NVFP4 让单位权重字节数下降；这些能力恰好把瓶颈推到权重搬运与 All-to-All 上。低秩补偿分支与这套硬件特性是互补的：低秩因子的矩阵乘是小维度 GEMM，适合 tcgen05 的批量调度；NVFP4/FP8 量化可与低秩因子共存，进一步压小 $S_{\\text{lr}}$；TMEM 让低秩聚合与补偿 GEMM 的累加器切换开销降低。换言之，硬件把“算”变便宜了，论文把“搬”变少了，两者叠加才能让 MoE 推理在有限带宽与专家并行拓扑下满足吞吐与延迟要求。</p>\n<p>但这条路径的工程代价必须被正视：低秩因子常驻显存、残差判定开销、回退触发的带宽尖峰、专家并行下切分带来的通信与同步成本。材料未给出秩、阈值、回退率与实验数字，因此容量规划不能依赖具体数值，只能把 $\\tau$、秩、回退比例作为运行时监控与联动调整的对象。一个可操作的判断是：把回退率、专家命中分布、带宽占用与尾延迟作为四个必看指标，回退率上升时先调 $\\tau$ 再调并行拓扑，而不是直接扩卡——因为扩卡不改变每 token 的权重读取结构，只改变 $E_h$ 的分布。这正是这篇论文把带宽优化落到路由后权重读取路径上的意义：它给了一个可调的回退式压缩旋钮，让容量规划从“堆算力”转向“控带宽”。</p>\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-7\">七 · 负载形态先于方案：输入长度、并发与批的三条约束线</h3>\n<p>低秩补偿方案的收益不是常数，它随请求形态漂移。工程上必须先固定三个测量口径，否则回退率与带宽节省无法比较。第一是输入长度分布：预填阶段的 token 数决定路由调用次数与分组 GEMM 的行数，长度分桶（例如按 512/2K/8K 分档）后每桶单独统计回退率，因为长请求的 token 更多、残差判定次数更多，回退 token 的绝对数量会被长请求放大。第二是并发：并发请求数决定批内 token 总量，进而决定一次分组 GEMM 覆盖多少专家；并发低时批内 token 少，激活专家数相对分散，低秩因子的读取更零碎，带宽节省被固定开销稀释。第三是批大小：批越大，分组 GEMM 的权重读取摊薄越好，但低秩因子常驻显存与 KV cache 同时增长，容量成为硬约束。</p>\n<p>三条线共同决定一个可核查的量：每 token 触发的专家权重字节数。定义批内第 $b$ 个请求长度为 $L_b$、批内 token 总数 $T=\\sum_b L_b$、批内激活的不同专家数为 $E_{\\mathrm{act}}$、回退 token 数为 $T_{\\mathrm{fb}}$，则每 token 平均专家权重读取字节可写成</p>\n<div class=\"formula\">$$B_{\\mathrm{token}}=\\frac{E_{\\mathrm{act}}\\cdot S_{W}+T_{\\mathrm{fb}}\\cdot S_{W}}{T}$$</div>\n<p>其中 $S_W$ 是单个专家权重的字节数（量化位宽决定）。这个式子把负载与方案绑在一起：$E_{\\mathrm{act}}$ 由路由与批内 token 分布决定，$T_{\\mathrm{fb}}$ 由残差阈值 $\\tau$ 与输入分布决定。测量时必须同时记录 $T$、$E_{\\mathrm{act}}$、$T_{\\mathrm{fb}}$ 与采样窗口内的 HBM 读写字节，四者缺一不可，否则无法判断带宽节省来自批变大还是回退变少。一个具体例子：同一模型在短请求高并发下 $T$ 大但 $E_{\\mathrm{act}}$ 接近专家总数上限，低秩路径的固定读取开销占比下降；而在长请求低并发下 $T$ 小、$E_{\\mathrm{act}}$ 分散，低秩因子按专家索引零散读取，带宽节省幅度明显收窄。这就是负载塑造方案的第一层含义。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-8\">八 · SLO 与长尾：回退率是尾延迟的直接输入</h3>\n<p>低秩补偿把计算图分成低秩路径与回退路径，调度器按 token 标记分流。分流本身增加少量判定与分支开销，但真正的 SLO 风险在回退触发的完整专家权重读取。回退 token 在批内是稀疏的，可一旦触发，就要读取该专家的完整权重 $W_e$，这笔读取与低秩因子的读取不在同一量级。尾延迟敏感场景下，单个批内若出现成簇回退，带宽需求瞬间抬升，批的完成时间被拉长，P99 延迟直接受回退比例支配。</p>\n<p>可核查的口径是把回退率定义为窗口内回退 token 数除以总 token 数 $r=T_{\\mathrm{fb}}/T$，并按批记录其方差。尾延迟的粗粒度模型可写成批完成时间由两部分构成：低秩路径的固定时间 $t_{\\mathrm{lr}}$ 与回退路径的带宽受限时间，后者正比于回退 token 触发的额外权重字节除以可用带宽 $BW$：</p>\n<div class=\"formula\">$$t_{\\mathrm{batch}}\\approx t_{\\mathrm{lr}}+\\frac{r\\cdot T\\cdot S_{W}}{BW}$$</div>\n<p>这个式子说明两件事。其一，$r$ 的波动比 $r$ 的均值更伤尾延迟：均值相同但方差大的负载，P99 会被少数高回退批拉高。其二，$BW$ 是专家并行下每卡可用的有效带宽，All-to-All 交换低秩中间激活与门控系数会占用同一份带宽预算，通信与回退读取争抢，尾延迟在拓扑拥塞时进一步恶化。工程判断是：SLO 约束应写成对 $r$ 的上界与对方差的上界，而不是只写平均吞吐目标。监控指标必须包含回退率、专家命中分布、带宽占用与尾延迟四项，回退率升高即意味着带宽收益被侵蚀，需联动调整 $\\tau$ 或并行拓扑。一个具体例子：解码阶段批内请求长度差异大，长请求持续产生 token，短请求早已结束，批内 token 分布偏移使某些专家的命中集中，回退在这些专家上成簇出现，尾延迟由这批专家决定，而非全局平均。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-9\">九 · 方案反过来限制负载：批大小与并发的可行域</h3>\n<p>方案不是被动接受负载，它给负载划出可行域。低秩因子按专家索引常驻或分片存放，专家数越多、秩越大，常驻显存越高，这部分显存与 KV cache、批内激活共同竞争容量。设专家数为 $N_e$、低秩因子每个专家的字节数为 $S_{\\mathrm{lr}}$、KV cache 每 token 字节数为 $S_{\\mathrm{kv}}$、批内 token 数为 $T$、模型与运行时固定占用为 $M_0$，则显存可行性约束为</p>\n<div class=\"formula\">$$N_e\\cdot S_{\\mathrm{lr}}+T\\cdot S_{\\mathrm{kv}}+M_0\\le M_{\\mathrm{avail}}$$</div>\n<p>这条不等式直接给出批大小的上界：低秩因子常驻占用越大，可容纳的 $T$ 越小，吞吐上限被压低。专家并行下低秩因子与专家权重同拓扑切分，单卡常驻量下降，但切分带来同步与切分边界的通信代价，All-to-All 只交换低秩中间激活与门控系数虽减小了跨卡体积，同步点仍会限制批的流水重叠。于是出现一个反向约束：为了摊薄分组 GEMM 的权重读取、提高吞吐，调度器想增大批；但增大批会推高 KV cache 与激活占用，挤占低秩因子常驻空间，或迫使降低秩、牺牲近似质量、推高回退率。这是一个闭环：批变大→回退率可能上升→带宽尖峰→尾延迟变差→SLO 要求限制批。容量规划必须在这个闭环里找可行点，而不是单独最大化批大小。</p>\n<p>可核查的测量口径是：固定并发与长度分布，扫描批大小，记录每档的 $r$、$E_{\\mathrm{act}}$、HBM 带宽占用、P50/P99 延迟与显存峰值。若某档批大小下显存峰值逼近上限且 $r$ 方差抬升，该档即为该负载形态下的可行上界。一个具体例子：在专家数多、秩较大的配置下，低秩因子常驻占用把可用批压到较小值，此时即便分组 GEMM 的摊薄效应存在，吞吐也被容量锁死；反之在专家数少、秩小的配置下，批可以放大，低秩路径的固定开销被摊薄，带宽节省更稳定。材料未给出具体秩与专家数数字，因此这套口径只能定性给出方向：常驻占用与批大小是此消彼长的关系。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-10\">十 · 预填与解码的负载分裂：两套口径不能混用</h3>\n<p>预填与解码的负载形态不同，低秩补偿的收益来源也不同，测量必须分开。预填阶段一次处理整段输入，token 数大、路由调用集中，分组 GEMM 行数多，$E_{\\mathrm{act}}$ 容易接近专家总数，低秩路径的读取被充分摊薄；此时带宽节省主要来自“用低秩因子替代全量专家矩阵”的读取量差，回退比例对总时间的影响相对可控，因为预填本身是计算与带宽混合受限。解码阶段每步只产生少量 token，批内 token 数小，$E_{\\mathrm{act}}$ 分散，低秩因子按专家索引零散读取，固定开销占比高；此时回退触发的完整权重读取更容易形成尖峰，因为单步时间短，一笔额外读取就能显著拉长该步。</p>\n<p>因此口径要拆成两组：预填侧记录每批 token 数、$E_{\\mathrm{act}}$、低秩路径与回退路径各自的权重字节、批完成时间；解码侧记录每步批内 token 数、专家命中分布、回退 token 数、步时间分布与 KV cache 占用。混用两组口径会把预填的摊薄效应误算到解码吞吐上，得出过于乐观的结论。一个具体例子：同一请求在预填阶段回退率低、带宽节省明显，进入解码后批内只剩该请求的少量 token，专家命中集中且零散，回退一旦触发就落在少数专家上，步时间被拉长，端到端尾延迟由解码段决定。工程上若只按预填数据做容量规划，解码段的 SLO 会被低估。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-11\">十一 · 长尾专家与命中分布：回退判定的粒度问题</h3>\n<p>路由的表达能力体现在长尾专家上：少数 token 被分配到低频专家，这些专家的低秩因子若秩不足，近似误差在长尾上累积，残差更容易超过 $\\tau$，回退集中发生在长尾专家。回退判定按 token 做，粒度较粗时，同一批内多个 token 落在同一长尾专家，回退读取被合并成一次较大的权重读取，形成带宽尖峰而非节省。可核查的口径是专家命中分布的偏度：记录窗口内每个专家的 token 计数，计算高频专家与低频专家的回退率之比。若长尾专家的回退率显著高于高频专家，说明低秩因子在长尾上的近似质量不足，$\\tau$ 的全局设定没有区分专家。</p>\n<p>一个可操作的思路是按专家分组设定阈值，而非全局单一 $\\tau$：对高频专家收紧阈值以保精度，对长尾专家放宽阈值以抑制回退尖峰，代价是长尾上的近似误差上升。这需要在测量中同时记录分组回退率与对应专家的输出偏差代理量（例如低秩近似残差的范数分布），否则无法判断放宽阈值是否越界。材料未给出具体阈值与回退率数字，因此这里只能给出判定方向：回退率在专家维度上的不均衡，是低秩补偿方案在长尾负载下的主要失效形态，监控必须按专家维度展开，而不是只看全局平均。带宽代价体现在尖峰：单次回退读取的字节数固定为 $S_W$，成簇回退使瞬时带宽需求叠加，尾延迟敏感场景需限制单批回退 token 的上界。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-12\">十二 · 可核查的测量清单与工程判断</h3>\n<p>把上述口径收敛成一张可执行的测量表，每项都要能对上采样窗口与负载分档。下表列出必测项与其对应的方案参数，测量时按长度桶、并发档、批大小档三维切分，避免把不同形态的负载混在一个均值里。</p>\n<table class=\"mini\"><thead><tr><th>测量项</th><th>口径</th><th>关联方案参数</th><th>代价维度</th></tr></thead><tbody>\n<tr><td>批内 token 总数 $T$</td><td>按批记录，分预填/解码</td><td>批大小、并发</td><td>吞吐、显存</td></tr>\n<tr><td>激活专家数 $E_{\\mathrm{act}}$</td><td>批内去重计数</td><td>路由、专家并行拓扑</td><td>带宽</td></tr>\n<tr><td>回退率 $r$ 及其方差</td><td>窗口内 $T_{\\mathrm{fb}}/T$，按批统计</td><td>残差阈值 $\\tau$、秩</td><td>尾延迟、带宽尖峰</td></tr>\n<tr><td>专家命中分布偏度</td><td>按专家计数，分高低频</td><td>低秩因子秩、分组阈值</td><td>精度、回退集中度</td></tr>\n<tr><td>HBM 读写字节</td><td>低秩路径与回退路径分开计</td><td>量化位宽、$S_W$</td><td>带宽占用</td></tr>\n<tr><td>显存峰值</td><td>低秩因子常驻 + KV cache + 激活</td><td>专家数、秩、批大小</td><td>容量上界</td></tr>\n<tr><td>P50/P99 批完成时间</td><td>分预填/解码</td><td>$\\tau$、并行拓扑</td><td>SLO</td></tr>\n</tbody></table>\n<p>工程判断落在闭环的收敛点上：低秩补偿的带宽收益由 $r$ 与秩共同决定，而 $r$ 又被负载形态（长度分布、并发、批大小）与 $\\tau$ 共同塑造；方案反过来通过常驻显存与回退尖峰限制批大小与并发可行域。容量规划的正确顺序是先按负载分档测出 $r$ 的均值与方差，再在显存约束下选批大小上界，最后用分组阈值压长尾回退，而不是先定批再测回退。材料未给出秩、阈值、回退率与实验数字，任何引用都不得补具体数值；可核验的只有机制与口径本身。若监控显示回退率方差随批增大而抬升，说明该负载形态下批已越过可行上界，应回调批大小或改并行拓扑，而不是继续加大批去摊薄分组 GEMM。</p>\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-13\">十三 · 低秩路径的 kernel 形状：从分组 GEMM 到补偿 GEMM</h3>\n<p>低秩补偿分支落到算子层面，不是一次 GEMM，而是两段形状完全不同的 GEMM 拼接。第一段按专家分组，对每个被选中的专家 $e$ 计算 $U_e V_e^{\\top} x$：$U_e$ 是 $d\\times r$ 的升维因子，$V_e$ 是 $r\\times d$ 的降维因子，$r$ 远小于 $d$。分组 GEMM 的 M 维是落到该专家的 token 数，N 维是 $d$，K 维是 $r$；由于 $r$ 很小，这条 GEMM 的算术强度低，属于典型的带宽受限算子——它的成本几乎正比于读入的因子字节数，而非 FLOPs。第二段是补偿 GEMM，只对残差超阈值的 token 触发，形状是 $W_e x$，K 维回到 $d$，算术强度显著上升。两段 GEMM 的 K 维相差一个数量级，因此不能共用同一套 tile 配置：低秩段适合较小的 K-tile 与更高的 N-tile，补偿段则应复用常规专家 GEMM 的 tile 与流水。</p>\n<p>把两段拼在一个 kernel 里还是拆成两个 kernel，是第一个工程判断。融合的好处是残差判定与门控加权可以在寄存器或共享内存里完成，省一次中间张量往返显存；代价是 kernel 内出现数据依赖的分支，warp 之间负载不均——未回退的 token 早早结束，回退的 token 还要读 $W_e$，同一 CTA 内的 warp 发散会拉长尾延迟。拆成两个 kernel 的好处是补偿段可以按回退 token 重新聚合成紧凑的批次，用满 tile；代价是低秩中间结果必须落显存，多一次写和一次读。在专家并行下，这个选择还牵连 All-to-All：若融合，低秩中间激活在 kernel 内即被消费，跨卡交换的只有门控系数；若拆分，低秩中间激活要先交换再补偿，跨卡体积变大。</p>\n<p>分组 GEMM 的索引方式同样影响带宽。按专家索引常驻的低秩因子若在显存中按专家连续排布，每个专家的 $U_e$ 与 $V_e$ 相邻，则一个 CTA 处理一个专家时只触碰一段连续地址，TLB 与 L2 命中率好；若按 token 顺序排布，同一 CTA 会在多个专家的因子间跳转，L2 失效概率上升。工程上应把因子按专家主序存放，并用一个 token→专家的置换表驱动分组，这与常规 MoE 分组 GEMM 的做法一致，但因子尺寸小，置换表的相对开销更突出——置换本身是一次小规模 scatter，其延迟在解码阶段的小批量下不可忽略。</p>\n<div class=\"formula\">$$\\text{bytes}_{\\text{lowrank}}=\\sum_{e\\in\\mathcal{A}} n_e\\cdot\\big(2r\\,b_{\\text{fac}}\\big),\\qquad \\text{bytes}_{\\text{full}}=\\sum_{e\\in\\mathcal{A}} n_e\\cdot\\big(2d\\,b_{W}\\big)$$</div>\n<p>逐项解释：$\\mathcal{A}$ 是本批激活的专家集合，$n_e$ 是落到专家 $e$ 的 token 数，$b_{\\text{fac}}$ 与 $b_W$ 分别是因子与专家权重的每元素字节数，系数 2 表示读入 $U_e$ 与 $V_e$（或 $W_e$）两份矩阵。比值 $\\text{bytes}_{\\text{lowrank}}/\\text{bytes}_{\\text{full}}\\approx r/d\\cdot b_{\\text{fac}}/b_W$，这就是带宽节省的上界；回退项把这部分节省按回退比例抵消。举例：$d$ 取数千量级、$r$ 取数十量级时，比值落在百分之一量级，但这是上界，实际节省要被回退率打折。系统代价上，这条公式直接对应显存带宽占用：低秩段省下的字节数就是分组 GEMM 的读带宽，而补偿段每触发一个 token 就重新引入 $2d\\,b_W$ 字节，回退率是带宽预算的一阶变量。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-14\">十四 · 数据类型：FP16/BF16 基线、FP8 与 NVFP4 的位宽账</h3>\n<p>低秩因子与专家权重可以取不同精度，这是本方法在 Blackwell 上最直接的杠杆。基线是 BF16：动态范围与 FP32 同阶，尾数 8 位，做低秩近似时因子本身的舍入误差较小，适合残差判定敏感的场合。FP16 尾数 10 位、范围窄，因子数值若超出范围需缩放，工程上不如 BF16 省心。FP8 分 E4M3 与 E5M2 两档：E4M3 尾数 3 位、范围较小，适合权重与激活；E5M2 范围大、尾数 2 位，多用于梯度类场景。NVFP4 是 Blackwell 档位上的 4 位浮点块格式，元素为 E2M1，配合块级缩放因子使用，位宽约为 FP8 的一半，带宽账上最省，但尾数只有 1 位，量化误差显著。</p>\n<p>关键判断是：低秩因子与专家权重不必同精度。因子尺寸小、常驻显存，用较高精度（BF16 或 FP8）能压低近似误差，减少回退；专家权重是带宽大头，用 NVFP4 或 FP8 能放大节省。但两者混用时，残差 $\\mathrm{res}_e$ 是两个不同精度路径之差，其数值分布被量化噪声污染，阈值 $\\tau$ 的判定会变得更粗——量化噪声本身可能超过 $\\tau$，导致大量 token 被误判回退，带宽节省被侵蚀。工程上应让因子的量化误差显著小于 $\\tau$，或在残差判定前对低秩结果做一次反量化对齐。</p>\n<table class=\"mini\"><thead><tr><th>格式</th><th>位宽/元素</th><th>尾数位</th><th>在本方法中的位置</th><th>主要代价</th></tr></thead><tbody><tr><td>BF16</td><td>16</td><td>8</td><td>因子基线、残差判定</td><td>因子常驻显存翻倍</td></tr><tr><td>FP16</td><td>16</td><td>10</td><td>因子可选</td><td>范围窄，需缩放</td></tr><tr><td>FP8 E4M3</td><td>8</td><td>3</td><td>因子或权重</td><td>量化噪声接近阈值量级</td></tr><tr><td>NVFP4</td><td>4 + 块缩放</td><td>1</td><td>专家权重首选</td><td>尾数过短，回退率上升</td></tr></tbody></table>\n<p>系统代价要按路径分开算。因子常驻显存：专家数为 $E$、秩为 $r$、维度为 $d$ 时，因子总字节约为 $E\\cdot 2dr\\cdot b_{\\text{fac}}$，BF16 下这条占用随 $E$ 与 $r$ 线性增长，会与 KV cache 争抢容量。权重带宽：专家权重从 BF16 降到 NVFP4，单次全量读取的字节数减半再减半，但回退触发的尖峰也按同比例缩小——尖峰的绝对幅度下降，相对幅度（相对于低秩段）不变。功耗上，低位宽 GEMM 的 Tensor Core 吞吐更高，单位 token 的计算能耗下降，但带宽受限时功耗更多花在显存子系统上，收益不如算力受限场景明显。一个具体例子：某专家被 64 个 token 选中，$d$ 取数千、$r$ 取数十，BF16 因子读取量为 $64\\times 2rd$ 字节量级，若权重为 NVFP4，全量读取为 $64\\times 2d\\times 0.5$ 字节量级，两者相差约 $4r$ 倍——这个倍数就是该专家在本批的带宽节省上界。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-15\">十五 · 累加精度与误差传播：残差判定的数值地基</h3>\n<p>低秩路径的累加精度决定残差 $\\mathrm{res}_e$ 是否可信。分组 GEMM 在 Tensor Core 上做 $U_e V_e^{\\top}x$，K 维是 $r$，累加链短，FP32 累加器足以吸收因子量化的舍入；但补偿段 $W_e x$ 的 K 维是 $d$，累加链长，若用 FP16 累加，长链求和会出现明显的舍入累积，残差被系统性高估或低估。工程上两条路径都应使用 FP32 累加器，Tensor Core 的 FP32 accumulate 是标准配置，代价是累加器占寄存器与共享内存，tile 尺寸受限于寄存器压力。</p>\n<p>误差传播的链条是：因子量化误差 → 低秩近似误差 → 残差估计偏差 → 回退判定偏差 → 带宽与精度权衡偏移。设因子量化引入的相对误差为 $\\epsilon_f$，则低秩结果 $\\hat y_{\\text{lr}}$ 与真值之差约为 $\\|U_eV_e^\\top x\\|\\cdot\\epsilon_f$ 量级；残差判定比较的是 $\\|\\mathrm{res}_e\\|$ 与 $\\tau$，若 $\\tau$ 与 $\\epsilon_f\\|U_eV_e^\\top x\\|$ 同量级，判定就被噪声主导。这就是为什么阈值不能设得过小：阈值越小，回退越多，但判定本身越不可靠，回退的 token 里混入大量本不需要补偿的样本，带宽尖峰变成常态。</p>\n<div class=\"formula\">$$\\|\\mathrm{res}_e\\|=\\big\\|W_ex-U_eV_e^\\top x\\big\\|\\le\\|W_ex\\|\\cdot\\big(\\epsilon_W+\\epsilon_f\\big)+\\|W_ex-U_eV_e^\\top x\\|_{\\text{true}}$$</div>\n<p>逐项解释：左边是 kernel 实际算出的残差范数；右边第一项是量化噪声上界，$\\epsilon_W$ 与 $\\epsilon_f$ 分别是权重与因子的相对量化误差，二者叠加；第二项是真实的低秩近似误差，由秩 $r$ 决定，与量化无关。这个不等式说明实测残差是真实误差与量化噪声的混合，阈值 $\\tau$ 必须显著高于噪声项，否则判定失去意义。系统代价上，累加精度换来的不只是数值正确性，还有回退率的可预测性：FP32 累加让残差估计稳定，调度器才能按回退率做容量规划；若累加精度不足，回退率随批次波动，尾延迟不可控。具体例子：同一批 token 在 FP16 累加下残差被高估，回退率上升，补偿 GEMM 的带宽尖峰把解码阶段的尾延迟推高；换 FP32 累加后残差回落，回退集中到真正误差大的长尾 token 上。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM、2-SM MMA 与第五代 Tensor Core</h3>\n<p>Blackwell 档位的第五代 Tensor Core 通过 tcgen05 指令族暴露给 kernel，其关键变化是矩阵乘的累加器落在 TMEM（Tensor Memory）而不是寄存器堆。对低秩路径这意味着：分组 GEMM 的 FP32 累加器不再挤占寄存器，tile 可以做得更大，K 维虽小但 N 维可以铺满，减少因 tile 过小导致的权重重复读取。TMEM 的容量是硬约束，一个 CTA 能驻留的累加器 tile 数有限，低秩段与补偿段若在同一 CTA 内先后执行，两段的 TMEM 占用要分时复用，否则会因 TMEM 不足而降 tile。</p>\n<p>2-SM MMA 是另一项直接相关的特性：两个 SM 协作完成一次矩阵乘，共享操作数，等效于把 MMA 的 M 或 N 维翻倍。对补偿段 $W_ex$ 这种 K 维长的 GEMM，2-SM 协作能提高 Tensor Core 利用率并减少权重从 L2 到共享内存的重复搬运；对低秩段，K 维只有 $r$，2-SM 的收益主要体现在 N 维铺开上，若 $r$ 太小，协作的同步开销可能盖过收益。工程判断是：补偿段优先用 2-SM MMA，低秩段按 $r$ 与批量决定是否启用——解码阶段批量小、$r$ 小，单 SM 的 tcgen05 更划算；预填阶段批量大，2-SM 能把因子读取的带宽摊薄。</p>\n<p>系统代价要落在具体资源上。TMEM 是新增的稀缺资源，它与共享内存、寄存器共同决定 occupancy；低秩因子常驻显存占用的是 HBM，TMEM 占用的是片上，两者不冲突但都限制并发 CTA 数。2-SM MMA 要求成对的 SM 同步，CTA 调度器需保证配对 SM 同时可用，在专家并行下跨卡负载不均时，配对失败会让部分 MMA 退化回单 SM，吞吐出现台阶式下降。第五代 Tensor Core 对 NVFP4 有原生支持，块缩放因子在 MMA 流水内被消费，这让权重低位宽化的带宽收益能真正落到 GEMM 上，而不是被反量化开销吃掉。具体例子：预填阶段一个批次激活多个专家，补偿段用 2-SM MMA 把 $W_e$ 的读取在兩个 SM 间共享，单次读取服务双倍 M 维 token；低秩段则用单 SM tcgen05，把 TMEM 留给累加器，避免与补偿段争抢。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-17\">十七 · 算子编排与系统代价：分流、尖峰与容量</h3>\n<p>把上述机制编排成一条推理路径，调度器要在 token 粒度上分流：路由给出 top-k 与门控系数后，低秩分组 GEMM 先跑，残差判定在 kernel 内或紧随其后完成，回退 token 被标记并聚合成补偿批。分流带来两类开销：判定开销（残差范数计算与阈值比较，每 token 一次归约）与分支开销（补偿批的重新聚合与 kernel 启动）。解码阶段批量小，kernel 启动延迟占比高，分流应尽量融合进低秩 kernel 的尾部；预填阶段批量大，拆成独立补偿 kernel 更能用满 tile。</p>\n<p>带宽尖峰是这条路径的结构性代价。低秩段的带宽占用平稳，正比于激活专家数与因子尺寸；补偿段一旦触发，按回退 token 数读取完整专家权重，瞬时带宽需求跳升。尾延迟敏感的场景要限制回退比例，手段有二：抬高阈值 $\\tau$ 减少回退，或对回退 token 做限流、分批补偿。前者牺牲近似精度，后者拉长补偿的完成时间。容量规划要把尖峰算进去：按平均带宽做预算会在尖峰时打满 HBM，SLO 抖动；按尖峰带宽做预算则平均利用率低。工程上取一个回退比例上限，把尖峰幅度约束在预算内，再用监控的回退率反馈调阈值。</p>\n<p>显存预算是另一条硬约束。低秩因子常驻占用与 KV cache、批大小共同分 HBM：专家数多、秩大时因子占用上升，批大小被迫压缩，吞吐下降；秩小则因子占用低但近似误差大、回退多，带宽尖峰频繁。这是一个二维权衡，容量规划要同时扫秩与阈值。专家并行下因子按专家切分常驻各卡，切分带来的同步成本体现在 All-to-All 的门控系数交换与补偿段的跨卡聚合上，跨卡激活体积虽小于全量交换，但同步点增多，流水被打断的次数上升。具体例子：一个解码批次在回退率升高时，补偿段的带宽尖峰把单步延迟推高，调度器降低批大小以守住 SLO，吞吐随之下降；此时若把阈值抬高，回退率回落，批大小恢复，但长尾专家的近似误差累积，输出质量需另行监控。</p>\n<p>最后的工程判断落在阈值与秩的联动上：$\\tau$ 不是孤立的精度旋钮，它与因子位宽、累加精度共同决定残差判定的信噪比；$r$ 不是孤立的带宽旋钮，它与因子常驻显存、TMEM 占用共同决定 occupancy。Blackwell 的 tcgen05 与 2-SM MMA 把算力侧的约束放松，瓶颈更彻底地落到 HBM 带宽与片上容量上，因此这条路径的调参顺序应是先定因子位宽与累加精度保证判定可信，再定秩与阈值分配带宽与显存预算，最后按回退率监控联动批调度。</p>\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-18\">十八 · 显存账本的三层结构：权重、激活、KV</h3>\n<p>在 Blackwell 上做 MoE 推理的显存规划，第一件事是把“显存”拆成三本互不相同的账。权重账是静态的、按专家并行切分后常驻的部分，包含完整专家矩阵 $W_e$、注意力权重、以及本文方法额外引入的低秩因子 $U_e V_e^{\\top}$；激活账是动态的、随批大小与序列长度波动的部分，包含分组 GEMM 的中间结果、All-to-All 交换缓冲、以及残差判定所需的临时张量；KV cache 账则是随解码步数线性增长、与并发请求数成正比的部分。三本账的增长率完全不同：权重账一次分配后基本不变，激活账随批大小阶跃式变化，KV 账随 token 数连续爬升。容量规划的错误几乎都来自把三者混成一个“显存够不够”的粗算。</p>\n<p>低秩补偿方法在这三本账上各插了一笔。权重账上，每个专家多出 $U_e$（$d\\times r$）与 $V_e$（$r\\times d$）两块因子，专家数 $E$ 与秩 $r$ 共同决定这笔常驻开销；激活账上，分组 GEMM 先聚合低秩贡献，中间激活的宽度从完整专家输出收缩到低秩路径的维度，但残差判定需要保留低秩结果与输入以计算 $\\|\\mathrm{res}_e\\|$，这是一笔额外但有限的临时占用；KV 账本身不变，但批大小受低秩因子常驻占用挤压，间接影响 KV 能分到多少。三者的耦合点就在批大小：批越大，激活账与 KV 账越高，而权重账不变，于是每 token 摊到的权重带宽下降、但显存压力上升。</p>\n<p>把账本写成可复算的形式，设隐维 $d$、专家数 $E$、每卡分到的专家数 $E_p=E/P$（$P$ 为专家并行度）、秩 $r$、批内 token 数 $B$、序列长度 $S$、KV 头数与每头维度之积为 $d_{kv}$、层数 $L$、KV 位宽 $b_{kv}$。权重账（每卡）为 $E_p\\cdot(d^2\\cdot b_w + 2dr\\cdot b_r)$，其中 $b_w$、$b_r$ 分别是专家权重与低秩因子的每元素字节数；KV 账为 $B\\cdot S\\cdot L\\cdot d_{kv}\\cdot b_{kv}$（按 K 与 V 两份计则再乘二）。这两条式子就是后面所有取舍的出发点。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-19\">十九 · 低秩因子的常驻代价与回退的带宽尖峰</h3>\n<p>低秩因子常驻显存是本文方法最直接的容量代价。以 $d$ 为隐维、秩 $r$ 远小于 $d$ 时，单专家因子占用约 $2dr\\cdot b_r$ 字节，相对完整专家 $d^2\\cdot b_w$ 的比例约为 $2r b_r/(d\\, b_w)$。当 $r/d$ 很小、且因子用比权重更窄的位宽存放时，这笔开销可以压到权重账的百分之几量级；但专家数 $E$ 很大时，绝对量仍不可忽略——专家并行把 $E$ 切成 $E_p$ 份，每卡只常驻自己那份因子，于是常驻占用随 $E_p$ 线性增长，而 $E_p$ 又受拓扑约束。这就是“专家数越多、秩越大，常驻占用越高”的定量来源。</p>\n<p>与常驻代价相对的是回退触发的带宽尖峰。低秩路径的权重读取量是 $E_p\\cdot 2dr\\cdot b_r$ 量级，回退路径则要为每个被标记的 token 读取对应专家的完整 $W_e$。设回退比例为 $\\rho$（被标记 token 占该批 token 的比例），则每批的专家权重读取字节数近似为</p>\n<div class=\"formula\">$$M_{\\text{bw}} \\approx B\\cdot\\big[(1-\\rho)\\cdot 2dr\\cdot b_r + \\rho\\cdot d^2\\cdot b_w\\big]\\cdot\\frac{k}{P}$$</div>\n<p>其中 $k$ 为 top-k。这个式子的含义很直接：$\\rho$ 从 0 上升时，读取量从低秩项平滑过渡到全量项，但过渡不是线性的——只要 $\\rho$ 稍微抬头，$d^2 b_w$ 项就以 $d/(2r)$ 的倍数压过低秩项。举例来说，若 $d=4096$、$r=64$、$b_r=b_w$，则 $d/(2r)=32$，即一个回退 token 的权重读取量相当于 32 个纯低秩 token。回退率从 1% 涨到 5%，带宽账就翻了数倍。这正是“回退率升高会侵蚀带宽收益”的机制根源，也是尾延迟敏感场景必须限制回退比例的原因：尖峰不是均匀分摊到整批，而是集中在被标记的那部分 token 上，形成批内的带宽长尾。</p>\n<p>系统代价因此分成两半：常驻显存是静态的、可预算的；带宽尖峰是动态的、随负载与阈值漂移的。前者挤压 KV 与批大小，后者直接冲击 SLO。工程上要把两者分开监控——常驻占用看“每卡权重账占 HBM 的比例”，尖峰看“批内回退 token 的权重读取字节数相对批均值的倍数”。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-20\">二十 · 分页、压缩、复用、卸载：四类手段各自打在哪本账上</h3>\n<p>分页（paging）主要打在 KV 账上。把 KV cache 按固定大小的页管理，按请求实际长度分配，消除按最大长度预留造成的内部碎片；对变长请求为主的负载，分页能把 KV 账从“按峰值预留”降到“按实际占用加少量页表开销”。它与本文方法的关系是间接的：低秩因子常驻占用越少，留给 KV 页池的容量越大，可容纳的并发请求越多，批大小才上得去。</p>\n<p>压缩打在权重账与 KV 账两处。权重侧，低秩因子本身就是一种结构化压缩——用 $U_e V_e^{\\top}$ 近似 $W_e$，把读取量从 $d^2$ 降到 $2dr$；它与 NVFP4/FP8 量化可以叠加，量化压低 $b_w$ 与 $b_r$，低秩压低元素个数，两者相乘才是最终带宽。KV 侧的压缩（更窄的 KV 位宽、按头或按层的差异化精度）压低 $b_{kv}$，直接缩小 KV 账。要注意的是，量化位宽会改变上式中 $d/(2r)$ 的等效倍数：若低秩因子用更窄位宽、完整权重用较宽位宽，回退的相对代价还会被放大。</p>\n<p>复用打在激活账与权重账的交界处。解码阶段复用常驻低秩因子，避免每步重新加载；同一批内多个 token 命中同一专家时，分组 GEMM 把它们的低秩贡献合并计算，权重读取只发生一次——这是 MoE 分组 GEMM 的固有收益，低秩路径把它放大：因子更小，合并后每专家的读取更便宜，命中分布越集中，复用率越高。反过来，专家命中分布越分散，复用的分母越大，低秩路径的相对优势越明显，但 All-to-All 的跨卡体积也越大。</p>\n<p>卸载（offload）打在权重账上，把冷专家或大秩因子放到主机内存或远端，按需换入。它与回退机制天然耦合：回退路径本来就要读完整权重，若该专家已被卸载，回退就变成一次换入加计算，延迟从“读 HBM”变成“读 PCIe/NVLink”，量级差异巨大。因此卸载策略必须与残差阈值联动——阈值调低会让更多 token 走回退，卸载专家的换入频率随之上升，尾延迟被换入带宽主导。工程判断是：只对命中率极低的专家做卸载，且这些专家的 $\\tau$ 判定要更保守，避免把回退引到慢路径上。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-21\">二十一 · 带宽瓶颈的位置：HBM3e 容量与读取量的对账</h3>\n<p>Blackwell 档位的 HBM3e 提供大容量与高带宽，但容量与带宽是两个独立的约束，不能互相折算。容量决定“能不能放下权重账加 KV 账加激活账”，带宽决定“每 token 要读多少字节、能不能在 SLO 内读完”。MoE 推理的带宽瓶颈不在算力侧，而在专家权重的搬运：路由把 token 分散到多个专家，分组 GEMM 的权重读取量随激活专家数增长，专家并行又把这份读取摊到多卡并经 All-to-All 交换激活。低秩补偿改的正是这条路径的分子——把每 token 触发的专家权重字节数从全量降到低秩因子加少量补偿。</p>\n<p>把容量账写成可复算的预算：设单卡 HBM 容量为 $C$（以字节计，具体档位数值按部署时实测填），则需满足</p>\n<div class=\"formula\">$$C \\;\\ge\\; \\underbrace{E_p\\big(d^2 b_w + 2dr b_r\\big)}_{\\text{权重账}} \\;+\\; \\underbrace{B\\,S\\,L\\,d_{kv}\\,b_{kv}\\cdot 2}_{\\text{KV 账}} \\;+\\; \\underbrace{A_{\\text{act}}(B,k,r)}_{\\text{激活账}} \\;+\\; \\underbrace{M_{\\text{other}}}_{\\text{框架/通信缓冲}}$$</div>\n<p>其中 $A_{\\text{act}}$ 随批大小与 top-k 增长，$M_{\\text{other}}$ 包含 NCCL/NIXL 通信缓冲与运行时开销。给定 $C$ 与权重账后，剩余容量在 KV 与激活之间分配，而批大小 $B$ 同时出现在 KV 账与激活账里——这就是“批大小受显存带宽与回退率约束”的算术表达：$B$ 越大，KV 与激活越高，但每 token 摊到的权重读取越低；回退率 $\\rho$ 越高，带宽尖峰越尖，允许的 $B$ 越小。</p>\n<p>具体例子：设 $d=4096$、$E_p=8$、$r=64$、$b_w=b_r=1$ 字节（示意性位宽，实际按部署量化方案填）、$L=32$、$d_{kv}=1024$、$b_{kv}=1$ 字节、$S=4096$。权重账约 $8\\times(4096^2+2\\times4096\\times64)\\approx 8\\times(16.8\\text{M}+0.5\\text{M})\\approx 138\\text{M}$ 字节；KV 账每请求约 $4096\\times32\\times1024\\times2\\approx 268\\text{M}$ 字节。可见在这个配置下，KV 账对批大小极其敏感——每多一个满长度并发请求就多出数百 MB，而权重账相对固定。若把 $r$ 翻倍，权重账只增约 4%，但低秩路径的带宽读取翻倍、回退的相对倍数 $d/(2r)$ 减半。这就是秩的取舍：秩小省带宽但近似误差大、回退多；秩大误差小但常驻与读取都涨。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-22\">二十二 · 残差判定与调度器的联动：把阈值变成容量旋钮</h3>\n<p>残差阈值 $\\tau$ 表面上是精度旋钮，实质上是容量与带宽的旋钮。判定逻辑是：对每个 token 的每个选中专家，计算 $\\|\\mathrm{res}_e\\|=\\|W_e x-U_eV_e^{\\top}x\\|$，超过 $\\tau$ 则标记回退。实现上不必真的先算完整 $W_e x$ 再比较——那等于把回退的读取提前做了，带宽节省归零。可行的做法是用低秩路径的中间量估计残差上界，或用采样近似，只在估计值接近 $\\tau$ 时才真正读取完整权重做精确判定。这一步的判定开销本身是激活账里的一笔：每个 token 每个专家一次范数计算，量级远小于一次 $d^2$ 读取，但批大、$k$ 大时不可忽略。</p>\n<p>调度器按 SLO 调整批大小与回退比例，机制上是双环控制：外环看尾延迟与带宽占用，若回退率上升导致尖峰，就调高 $\\tau$（更少回退）或缩小批；内环看专家命中分布，若命中过于分散导致 All-to-All 体积膨胀，就调整并行拓扑或路由策略。这里有个反直觉的耦合：调高 $\\tau$ 减少回退、省带宽，但近似误差上升，可能触发更多下游重试或质量回退；调低 $\\tau$ 提高精度，但带宽尖峰更频繁，SLO 稳定性下降。阈值不是单调优化量，而是在“带宽节省”与“尾延迟稳定”之间的显式权衡点。</p>\n<p>监控指标应包含回退率、专家命中分布、带宽占用与尾延迟四项，缺一不可：只看回退率会漏掉命中分布变化带来的 All-to-All 膨胀；只看带宽均值会漏掉批内尖峰；只看尾延迟会误判为算力不足而实际是回退路径的慢读。工程判断是：把回退率与尾延迟做成联动告警，回退率越过某条线时先冻结批大小扩张，再评估是否调阈值或改拓扑。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-23\">二十三 · 与量化、KV 策略共存的边界条件</h3>\n<p>低秩补偿与 NVFP4/FP8 量化共存时，带宽节省是两者相乘而非相加：量化压低每元素字节数，低秩压低元素个数。但两者叠加有边界条件。其一，低秩因子的位宽若比完整权重更窄，回退的相对代价被放大（上式中 $b_w/b_r$ 进入 $d/(2r)$ 的等效倍数），回退率必须压得更低才划算。其二，量化误差与低秩近似误差会叠加，残差 $\\|\\mathrm{res}_e\\|$ 的分布随量化方案漂移，固定的 $\\tau$ 在不同量化配置下含义不同，部署时需按实际量化方案重新校准阈值，材料未给出具体位宽与校准方法，这一步只能靠实测。其三，低秩因子与专家权重同拓扑切分，切分粒度受专家并行度约束，若某卡分到的专家数很少，因子的切分可能退化为整块常驻，失去分片收益。</p>\n<p>KV 策略不变的前提是低秩因子不挤占 KV 页池。若权重账因因子常驻上升，KV 能分到的容量下降，分页策略的有效性随之下降——页池变小，碎片容忍度变低，长请求更容易被拒绝或排队。因此容量规划要把“因子常驻增量”从 KV 预算里预先扣除，而不是事后挤。一个可操作的判断：先按无低秩因子的基线算 KV 页池与最大并发，再把因子常驻增量当作固定扣除项重算，若最大并发跌破 SLO 要求，就降秩或减专家常驻，而不是动 KV 位宽——后者会同时影响精度与带宽，牵连面更大。</p>\n<p>最后落在机制上：本文方法的显存账本本质是把权重账的一部分从“全量专家矩阵”挪到“低秩因子加回退缓冲”，用静态常驻换动态带宽，用阈值把动态尖峰控制在 SLO 内。可复算的预算式给出容量下限，回退率给出带宽上限，两者共同决定批大小与并行拓扑的可行域。工程上真正要盯的不是秩或阈值的绝对值，而是回退率与专家命中分布在负载漂移下的稳定性——它们一变，账本的两端同时移动。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-24\">二十四 · 连续批处理在低秩补偿路径上的分流结构</h3>\n<p>低秩补偿把单个 token 的计算图劈成两支：低秩路径（读 $U_eV_e^\\top$ 做分组 GEMM）与回退路径（读完整 $W_e$ 做补偿 GEMM）。这两支的显存带宽特征完全不同——低秩路径的权重读取量正比于秩 $r$ 与专家数，回退路径正比于专家矩阵的完整尺寸。连续批处理（continuous batching）在普通 MoE 上只需按 token 数动态拼批，但在本方法下必须额外维护一个按 token 的回退标记位，调度器每步都要把新到达的 token 与在途 token 混编，并按标记位把同一批次切成两个子批次分别发射 GEMM。这意味着批不再是同质的：一个批次里可能 80% 的 token 走低秩路径、20% 走回退路径，两个子批次的形状不同、权重读取地址不同，无法合并成一次大 GEMM。</p>\n<p>具体机制上，调度器在每步迭代开始时做一次“标记聚合”：从路由结果里取出每个 token 的残差范数 $\\|\\mathrm{res}_e\\|$，与阈值 $\\tau$ 比较，得到布尔掩码 $m_t=\\mathbb{1}\\{\\|\\mathrm{res}_e\\|&gt;\\tau\\}$。低秩子批次取 $m_t=0$ 的 token 索引，回退子批次取 $m_t=1$ 的索引，两个子批次各自按专家索引排序后发射分组 GEMM。排序这一步不可省——分组 GEMM 的权重读取效率依赖同一专家的 token 在批内连续，乱序会让每个专家的权重被反复换入换出，带宽开销按专家数放大。代价是每步多一次索引排序与两次 kernel 发射，在解码阶段单步只有几十个 token 时，这次排序的固定开销占比不可忽略；在预填阶段 token 数上千时则可摊薄。</p>\n<p>系统代价的量化方式是：设批内 token 数为 $B$，回退率为 $\\rho$，则每步权重读取字节数近似为</p>\n<div class=\"formula\">$$ \\mathrm{Bytes}_{\\text{step}} \\approx B(1-\\rho)\\cdot r\\cdot(d_{\\text{in}}+d_{\\text{out}})\\cdot b_w \\;+\\; B\\rho\\cdot d_{\\text{in}}d_{\\text{out}}\\cdot b_w $$</div>\n<p>其中 $b_w$ 是每权重字节数（NVFP4 与 FP8 不同），$d_{\\text{in}},d_{\\text{out}}$ 是专家矩阵维度。第一项随 $r$ 线性增长，第二项与 $r$ 无关但被 $\\rho$ 缩放。当 $\\rho$ 从 0.1 升到 0.3，第二项翻三倍，带宽节省被迅速侵蚀——这正是连续批处理必须把 $\\rho$ 当作一等调度变量而非事后统计量的原因。举例：一个解码步 $B=64$、$r$ 取较小值、$\\rho=0.15$ 时，低秩项占带宽主体；若某步专家命中分布突然偏向长尾专家导致 $\\rho$ 跳到 0.4，该步带宽需求可能超过低秩项的若干倍，直接表现为该步延迟尖峰。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-25\">二十五 · Chunked prefill 与回退判定的时序耦合</h3>\n<p>Chunked prefill 把长预填请求切成固定 token 数的块，逐块与解码请求混批，目的是压住预填对解码尾延迟的冲击。在本方法下，chunked prefill 多了一层耦合：回退判定发生在低秩 GEMM 之后，也就是说一个 chunk 必须先算完低秩贡献、算出残差，才能知道哪些 token 要回退。若把整个 chunk 一次性送进低秩路径再统一判定，回退子批次会在 chunk 末尾集中爆发，形成一次带宽尖峰；若按更细的粒度（例如按专家分组）边算边判定，则可以把回退读取分散到 chunk 内的多个时间点。</p>\n<p>伪代码思路如下：对 chunk 内 token 按专家索引分桶，逐桶执行低秩 GEMM 并即时计算残差，残差超阈的 token 立即追加到回退队列，回退队列在桶间穿插发射，而不是等 chunk 结束。这样做的代价是低秩 GEMM 被切成多个小 GEMM，每个桶的矩阵规模变小、kernel 发射次数变多，tcgen05 的 MMA 利用率下降；收益是回退带宽被摊平，尾延迟的方差变小。工程判断是：chunk 越大、专家命中越集中，越值得用桶间穿插；chunk 很小（例如 512 token 以下）时切桶的固定开销可能超过摊平收益，此时宁可整 chunk 判定、把回退集中处理，靠后续批次的低秩 token 填补带宽空窗。</p>\n<p>另一个耦合点是 KV cache：chunked prefill 的每个 chunk 都要写 KV，而回退路径的补偿 GEMM 需要读该 token 的隐藏状态。若 chunk 的 KV 写入与回退 GEMM 争用同一段显存带宽，预填阶段的带宽压力会叠加。调度上应把回退 GEMM 安排在 KV 写入之后的独立时间片，或利用 Blackwell 的异步拷贝把 KV 写入与低秩 GEMM 重叠，把回退 GEMM 放到下一个 chunk 的低秩计算期间穿插执行。这要求调度器维护一个跨 chunk 的回退队列，队列长度受显存中待补偿 token 的隐藏状态占用约束——队列越长，常驻显存越多，与低秩因子、KV cache 三方争抢容量。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-26\">二十六 · 优先级、抢占与回退率的联动</h3>\n<p>尾延迟敏感场景下，调度器需要区分请求优先级：高优先级请求的 token 不能被低优先级请求的回退带宽尖峰拖慢。本方法给出的抓手是回退率 $\\rho$ 可按请求或按批次调节——对高优先级请求，可以临时调高阈值 $\\tau$（少回退、多近似），把带宽让给低优先级请求的回退；对低优先级请求则调低 $\\tau$ 保精度。这是一个显式的精度-带宽交换，代价是高优先级请求的近似误差上升，需要在 SLO 里区分“延迟 SLO”与“质量 SLO”。</p>\n<p>抢占（preemption）在 MoE 解码里通常表现为把在途请求的 KV cache 换出到主机内存再换入。本方法下抢占多了一个维度：低秩因子是常驻显存的，若显存紧张到需要换出低秩因子，换出后再换入的代价是重新读一遍因子权重，且换入时机与专家命中分布耦合——某个专家的因子刚被换出，下一步该专家又被命中，就会触发换入抖动。因此抢占策略应优先换出 KV cache 而非低秩因子，除非专家命中分布高度偏斜、少数专家的因子占了大部分常驻占用。工程上可对低秩因子按专家命中频率做冷热分级，冷专家因子换出、热专家因子常驻，换出粒度为单专家而非全局。</p>\n<p>系统代价体现在抢占的恢复路径上：被抢占请求恢复时，其历史 token 的回退标记已丢失，若重新判定会产生重复的回退 GEMM。调度器应把回退标记随 KV cache 一起持久化（每个 token 一位），恢复时直接复用，避免重复读取完整专家权重。这一位标记的存储开销相对 KV cache 可忽略，但换出换入的元数据管理会增加主机-设备拷贝的复杂度。举例：一个长请求在解码中途被抢占，恢复后若重新判定导致 10% 的 token 二次回退，这些 token 的完整专家权重被读两遍，带宽开销翻倍，尾延迟直接劣化。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-27\">二十七 · 分离式预填/解码下的回退归属</h3>\n<p>分离式（disaggregated）预填/解码把预填节点与解码节点分开，预填节点算完 KV 后把 KV 传给解码节点。本方法的回退判定发生在预填阶段的路由之后，问题随之而来：回退标记应该跟随 KV 一起传给解码节点，还是在解码节点重新判定？若跟随传递，解码节点可直接按标记分流，无需重算残差，省掉一次低秩 GEMM 的重复计算；若重新判定，解码节点要再读一遍低秩因子算残差，带宽开销增加，但可以按解码节点当前的阈值策略重新权衡（例如解码阶段更看重尾延迟，调高 $\\tau$ 减少回退）。</p>\n<p>传递方案的代价是元数据体积：每个 token 一位标记，加上门控系数（top-k 个浮点数），随 KV 一起跨节点传输。KV 传输本身已是分离式架构的带宽瓶颈，额外元数据占比很小，但门控系数若用 FP32 存储则体积不可忽略，可压到 FP8 与 NVFP4 权重方案对齐。重新判定方案的代价是解码节点每步多一次低秩 GEMM 的残差计算，这部分计算量与低秩路径本身同量级，等于把低秩路径算了两遍——只有在解码节点确实需要不同阈值策略时才值得。</p>\n<p>更细的机制是：预填节点在算低秩贡献时，可以把低秩中间激活（$U_eV_e^\\top x$ 的结果）一并缓存并传给解码节点，解码节点直接用它算残差，避免重算低秩 GEMM。这要求传输体积增加低秩中间激活，其维度是 $r$ 而非 $d_{\\text{out}}$，当 $r$ 远小于 $d_{\\text{out}}$ 时传输开销可控。工程判断是：分离式架构下应传“低秩中间激活 + 门控系数 + 回退标记”三元组，解码节点零重算即可分流；代价是预填节点的显存要暂存这些中间量直到传输完成，与预填阶段的批大小共同约束显存预算。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-28\">二十八 · 尾延迟的压制手段与带宽尖峰的观测</h3>\n<p>尾延迟的来源在本方法下高度集中在回退带宽尖峰：单步内回退 token 集中出现时，完整专家权重的读取把显存带宽打满，该步延迟远高于均值。压制手段有三类。其一是阈值平滑：不让 $\\tau$ 固定，而是按滑动窗口的回退率反馈调节——回退率上升时略微调高 $\\tau$ 抑制回退，回退率下降时调回，形成一个负反馈环。代价是精度随 $\\tau$ 波动，需要监控近似误差的累积。其二是回退预算：每步设定回退 token 数上限，超出的 token 延迟到下一步回退（用低秩结果先顶上），把尖峰摊到多步。代价是被延迟的 token 输出先用近似值，若下游对精度敏感则不可接受。其三是拓扑调整：把回退密集的专家分布到带宽更充裕的卡上，或增加该专家的并行度，从根上降低单卡带宽压力。</p>\n<p>观测上，调度器应把每步的回退率、专家命中分布、带宽占用与步延迟一起记录，形成四元组时间序列。回退率与步延迟的相关性可直接用来定位尖峰：若某步回退率并不高但延迟陡增，说明瓶颈不在回退带宽而在 All-to-All 同步或低秩因子的换入抖动；若回退率与延迟同步上升，则是回退带宽尖峰。这种区分对容量规划很关键——前者要调并行拓扑，后者要调 $\\tau$ 或回退预算。举例：一个 NVL72 机架内专家并行，某步回退率 0.2 但延迟翻倍，排查发现是低秩中间激活的 All-to-All 在跨 NVLink 域时与回退 GEMM 的权重读取争用同一段链路带宽，解法是把回退 GEMM 安排在 All-to-All 完成之后的时间片，而非与之重叠。</p>\n<p>最后落到一个具体机制上：调度器维护一个“回退信用”计数器，每步的回退预算按信用余额发放，余额由前几步的实际带宽占用与尾延迟反馈补充。信用机制把回退从“按 token 即时判定”变成“按预算延迟判定”，在保持低秩路径吞吐的同时把带宽尖峰削平；其工程代价是回退队列的显存占用与判定延迟，队列深度需与批大小、专家数、低秩因子常驻占用一起纳入显存预算，任何一项超配都会让信用机制失效、退化为无约束回退。</p>\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-29\">二十九 · 切分维度与低秩分支的落位</h3>\n<p>低秩补偿分支一旦进入推理图，并行切分就不再是“把专家权重摊到多卡”这么单一的问题，而是要在四套切分语义里给低秩因子找一个不冲突的落位。张量并行（TP）切的是单个专家矩阵的列或行，通信发生在每层 GEMM 之后；专家并行（EP）切的是专家集合本身，通信发生在路由之后；流水并行（PP）切的是层段，通信是激活的跨 stage 传递；数据并行（DP）切的是批次，通信是梯度或参数同步——推理侧通常退化为副本，不产生每 token 通信。低秩因子的特殊之处在于它有两个可切维度：按专家索引切（与 EP 同构），或按秩维度切（与 TP 同构）。论文给出的做法是与专家权重同拓扑切分，即第 $e$ 个专家的 $U_e$、$V_e$ 落在持有 $W_e$ 的那张卡上，这样回退路径触发时 $W_e$ 与 $U_e V_e^\\top$ 在同一显存、同一 SM 附近，补偿 GEMM 不需要额外跨卡取因子。</p>\n<p>代价立刻显现：EP 切分下每张卡只持有 $E/P$ 个专家的低秩因子（$E$ 为专家总数，$P$ 为 EP 度数），常驻显存按 $E/P$ 摊薄，但路由是全局的，任何卡上的 token 都可能命中任意专家，于是低秩中间激活必须跨卡流动。这正是 All-to-All 的入口。若改为按秩切分，每张卡持有全部专家的一个秩片段，All-to-All 体积变成秩片段而非完整激活，但回退判定需要跨卡归约残差范数，多了一次同步。两种切法的通信量级不同：前者是“激活体积 × 命中专家数”，后者是“秩片段体积 × 卡数 + 一次残差归约”。工程判断上，专家数多、单专家秩小的模型适合前者；专家数少、秩大的模型后者更省。</p>\n<div class=\"formula\">$$V_{\\text{a2a}}^{\\text{EP}} \\approx B \\cdot k \\cdot d \\cdot s, \\qquad V_{\\text{a2a}}^{\\text{rank}} \\approx B \\cdot k \\cdot r \\cdot P$$</div>\n<p>其中 $B$ 为批内 token 数，$k$ 为 top-k，$d$ 为隐维，$s$ 为激活字节数，$r$ 为秩。低秩分支把 $d$ 换成 $r$ 或把 $s$ 压到低秩中间激活的位宽，这就是“跨卡体积小于全量激活交换”的来源。举例：一个 top-2 路由、隐维数千、批内数千 token 的预填批次，全量激活 All-to-All 的字节量按 $B \\cdot k \\cdot d \\cdot s$ 估算已在数十 MB 量级，而低秩中间激活只传 $r$ 维投影结果，量级降一个档；但若 $r$ 接近 $d$，这个优势消失，切分反而多出残差归约的同步点。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-30\">三十 · NVLink 5 与 NVSwitch：All-to-All 的物理上限</h3>\n<p>GB200 NVL72 把 72 个 GPU 放进一个 NVLink 域，NVSwitch 提供全互联，任意两卡之间是单跳。这改变了 All-to-All 的成本结构：在传统 InfiniBand 拓扑上，All-to-All 的瓶颈是跨节点链路的对分带宽与多跳转发；在 NVSwitch 域内，瓶颈变成每卡的 NVLink 5 端口带宽与交换芯片的聚合吞吐。对低秩补偿而言，这意味着 EP 度数可以开到较大而不必担心多跳，但每卡出口带宽仍是硬约束——All-to-All 是“每卡向其余 $P-1$ 张卡各发一份”的模式，单卡发送量正比于 $P$，所以 EP 度数翻倍时单卡通信时间大致翻倍，除非用分层 All-to-All（先域内聚合再域间转发）。</p>\n<p>All-Reduce 在推理侧的出场频率低于 All-to-All，但在 TP 组内仍然存在：TP 的 GEMM 行切分需要每层一次 All-Reduce 合并部分和。低秩分支若按秩切分，残差范数的跨卡归约就是一个小规模 All-Reduce，它的延迟取决于归约算法（环形 vs 递归倍增）与消息大小。小消息走 NVLink 的延迟主要由软件栈与同步开销决定，而非带宽；因此把残差判定做成“每卡本地先算部分范数、再一次性归约”比逐 token 归约更划算。系统代价上，TP 组内的 All-Reduce 与 EP 的 All-to-All 共享同一批 NVLink 端口，两者叠加时会出现端口争用：预填阶段 TP 的激活 All-Reduce 与 EP 的专家分发同时进行，端口的有效带宽被瓜分，尾延迟上升。</p>\n<table class=\"mini\"><thead><tr><th>通信原语</th><th>触发点</th><th>低秩分支的影响</th><th>主要代价</th></tr></thead><tbody><tr><td>All-to-All（EP）</td><td>路由后分发激活</td><td>只传低秩中间激活与门控系数</td><td>单卡发送量正比于 EP 度数</td></tr><tr><td>All-Reduce（TP）</td><td>行切分 GEMM 后</td><td>残差范数归约复用同一组</td><td>与 All-to-All 争用端口</td></tr><tr><td>PP 激活传递</td><td>stage 边界</td><td>回退标记需随激活下传</td><td>stage 间气泡</td></tr><tr><td>NIXL 传输</td><td>跨节点/跨池 KV 与因子搬运</td><td>低秩因子可预取</td><td>与计算重叠不足则暴露</td></tr></tbody></table>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-31\">三十一 · NIXL 与分离式部署下的因子搬运</h3>\n<p>NIXL 是面向推理的传输层抽象，把显存到显存、显存到存储的搬运从具体链路（NVLink、RDMA、PCIe）里解耦出来，让调度器按拓扑选择路径。在分离式预填/解码部署里，预填节点算出路由结果与低秩中间激活，解码节点需要复用常驻低秩因子与 KV cache。低秩因子的一个有利性质是“按专家索引常驻、跨请求复用率高”：同一专家的 $U_e V_e^\\top$ 在不同请求间不变，因此可以在解码节点预热，用 NIXL 在预填阶段就把命中率高的专家因子预取过去，避免解码时首次命中造成的取因子停顿。这与 KV cache 的搬运形成竞争——两者都走同一批链路，预取因子会挤占 KV 传输带宽。</p>\n<p>工程上要区分两类传输：一是每 token 都发生的低秩中间激活交换（走 NVLink 域内 All-to-All），二是低频的因子预取与 KV 迁移（走 NIXL，可能跨节点）。前者对延迟敏感，后者对带宽敏感。若把因子预取做成后台异步、与预填计算重叠，则暴露的只有首次命中的冷启动；若同步预取，预填阶段的尾延迟会被拉长。一个具体例子：解码节点收到一批请求，路由分布集中在少数热门专家，预取这些专家的因子只需少量传输，收益是后续所有命中该专家的 token 都省掉一次远端取权重；反之长尾专家命中稀疏，预取成本摊不薄，不如让回退路径直接读本地分片。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-32\">三十二 · 通信何时成为瓶颈：三个判据</h3>\n<p>第一个判据是“计算-通信比”。低秩路径的分组 GEMM 计算量按 $B \\cdot k \\cdot d \\cdot r$ 估算，通信量按 $B \\cdot k \\cdot r \\cdot s$ 估算，两者之比约为 $d/s$——与批大小无关，只与隐维和激活位宽有关。这意味着低秩路径本身在 NVFP4/FP8 下计算密度不高，通信占比被动上升；一旦 EP 度数增大，All-to-All 的固定开销（同步、消息头、路由表查找）摊到每个 token 上，通信就可能压过计算。第二个判据是“回退率侵蚀”。回退触发的完整专家权重读取是本地显存带宽事件，不直接产生跨卡通信，但它拉长了分组 GEMM 的执行时间，使后续 All-to-All 的发起被推迟，流水线出现气泡；回退率越高，气泡越多，通信与计算的 overlap 越差。第三个判据是“端口争用”：TP 的 All-Reduce 与 EP 的 All-to-All 在同一 NVLink 端口上叠加，有效带宽按两者消息量分配，任一方的尾延迟都会被另一方拖长。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\!\\left(\\frac{C_{\\text{lr}}+C_{\\text{fb}}}{F},\\ \\frac{V_{\\text{a2a}}}{b_{\\text{link}}}\\right) + T_{\\text{sync}},\\qquad \\text{瓶颈在通信} \\iff \\frac{V_{\\text{a2a}}}{b_{\\text{link}}} &gt; \\frac{C_{\\text{lr}}+C_{\\text{fb}}}{F}$$</div>\n<p>$C_{\\text{lr}}$ 为低秩路径计算量，$C_{\\text{fb}}$ 为回退补偿计算量，$F$ 为有效算力，$b_{\\text{link}}$ 为单卡有效出口带宽，$T_{\\text{sync}}$ 为同步开销。这个不等式给出可操作的判断：当批大小受显存带宽约束而无法增大时，$C$ 项上不去，$V_{\\text{a2a}}$ 却随 EP 度数增长，通信成为瓶颈；此时应降低 EP 度数、改用秩切分，或把低秩中间激活进一步量化以压 $s$。反之，当回退率高、$C_{\\text{fb}}$ 主导时，瓶颈回到本地显存带宽而非网络，调阈值比调拓扑更有效。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-33\">三十三 · 拓扑与阈值的联动调参</h3>\n<p>残差阈值 $\\tau$ 与并行拓扑不是两个独立旋钮。阈值降低，回退率上升，本地完整专家权重读取增加，分组 GEMM 时间变长，All-to-All 的发起被推迟，通信与计算的重叠窗口缩小；阈值升高，回退率下降，低秩路径变快，All-to-All 更频繁地成为关键路径，跨卡激活体积成为主导。于是存在一个由拓扑决定的“最优点”：EP 度数大、NVLink 端口紧张时，应把 $\\tau$ 调低以减少跨卡流量占比（代价是本地带宽上升）；EP 度数小、端口富余时，应把 $\\tau$ 调高让低秩路径承担更多计算，把通信压到次要位置。这个联动在容量规划里表现为：给定 SLO 的尾延迟上限，先按拓扑估出 $V_{\\text{a2a}}/b_{\\text{link}}$ 的下界，再反推允许的回退率上限，最后落到 $\\tau$ 的取值区间。</p>\n<p>一个具体机制是“按专家命中分布分区调阈值”：热门专家的低秩因子常驻且复用率高，近似误差在大量 token 上被平均，可以放宽 $\\tau$；长尾专家命中稀疏，单次回退的带宽尖峰摊不薄，应收紧 $\\tau$ 或直接走完整权重路径而不做低秩近似。调度器可以在批级别统计命中分布，把长尾专家的 token 集中成小批，避免它们的回退尖峰与热门专家的低秩路径在同一时间窗内争用带宽。代价是分批带来额外的调度开销与批内 token 数下降，吞吐与尾延迟之间需要显式取舍。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-34\">三十四 · 监控指标与失败模式</h3>\n<p>监控应至少覆盖四项：回退率（按专家、按批）、专家命中分布的偏斜度、NVLink 端口占用率、以及分组 GEMM 与 All-to-All 的重叠比例。回退率升高会直接侵蚀带宽收益，但它的影响不是线性的——回退集中在少数 token 时，尖峰被平均掉；回退弥散到大批 token 时，本地带宽与跨卡通信同时吃紧。重叠比例是判断通信是否成为瓶颈的直接信号：重叠比例下降说明计算与通信串行化，此时增加批大小未必有用，因为瓶颈已不在算力。失败模式有三类可辨识的形态：其一，低秩因子常驻显存与 KV cache 争用，导致批大小被迫下调，吞吐不升反降；其二，残差判定过粗，把本可低秩近似的 token 误判为回退，造成带宽尖峰而非节省；其三，EP 切分下因子与权重的落位不一致，回退时需跨卡取因子，补偿 GEMM 变成通信事件。第三类最隐蔽，因为它只在回退路径上暴露，监控若只看平均带宽会漏掉。</p>\n<p>工程判断落在切分一致性上：低秩因子与专家权重必须同拓扑落位，回退路径的补偿 GEMM 才能保持本地性；一旦为了显存均衡把因子挪到别的卡，回退就从本地带宽事件变成跨卡通信事件，尾延迟的分布被拉长。因此在容量规划阶段，应把“因子落位”作为与“专家落位”并列的约束写入拓扑配置，而不是事后按显存余量自由摆放。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-35\">三十五 · 并行拓扑下的通信边界与失效条件</h3>\n\n<p>低秩补偿改变的不只是单卡权重读取量，它同时改写了并行切分的成本结构。TP 切分下，低秩因子 $U_eV_e^\\top$ 按列或按行分片，每张卡只持有专家矩阵的一个切片，低秩路径的分组 GEMM 在片内完成，几乎不引入额外集合通信；代价是 TP 组内仍需对部分和做 All-Reduce，而低秩因子的秩若小于 TP 度，分片粒度会碎到无法填满 tcgen05 的 MMA 形状，算力利用率反而下降。EP 切分是这套方案的主战场：低秩因子与完整专家权重同拓扑常驻，All-to-All 只搬运低秩中间激活 $U_eV_e^\\top x$ 与门控系数 $g_e(x)$，跨卡体积按秩 $r$ 而非隐藏维 $d$ 缩放，比值约为 $r/d$。PP 切分下低秩分支应整体落在持有该层专家的 stage 内，跨 stage 只传残差判定后的回退标记，避免把补偿 GEMM 拆到两个 pipeline stage 之间造成气泡。DP 切分与低秩补偿基本正交，但副本间的批调度若不同步，回退率会在副本间抖动，容量规划需按最坏副本而非均值估算带宽。</p>\n\n<p>通信成为瓶颈的判据可以写成一个可测的不等式。设单卡可用 HBM 带宽为 $B_{\\mathrm{hbm}}$、NVLink 5 单向有效带宽为 $B_{\\mathrm{nv}}$、每 token 低秩路径读取字节数为 $S_{\\mathrm{lr}}$、All-to-All 每 token 交换字节数为 $S_{\\mathrm{a2a}}$、回退率为 $\\rho$、完整专家权重字节数为 $S_{W}$，则低秩路径与通信的时间比近似为</p>\n\n<div class=\"formula\">$$T_{\\mathrm{lr}}/T_{\\mathrm{a2a}} \\approx \\frac{(1-\\rho)\\,S_{\\mathrm{lr}}+\\rho\\,S_{W}}{B_{\\mathrm{hbm}}}\\Big/\\frac{S_{\\mathrm{a2a}}}{B_{\\mathrm{nv}}}$$</div>\n\n<p>当该比值显著大于 1 时，All-to-All 不是瓶颈，带宽优化落在权重读取上；当 $\\rho$ 升高使分子膨胀，或 EP 度增大使 $S_{\\mathrm{a2a}}$ 随跨卡专家数线性增长时，比值翻转，通信与回退尖峰共同主导尾延迟。工程上应把 $\\rho$ 与 EP 度作为联合旋钮：EP 度提高可降低单卡常驻专家数、缓解显存压力，但 All-to-All 跳数与 NVSwitch 域内争用上升；$\\rho$ 提高则把流量从 NVLink 拉回 HBM，两者不是独立可调的。</p>\n\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制</th><th>系统代价</th></tr></thead><tbody><tr><td>回退率尖峰</td><td>长尾专家残差集中超阈值，补偿 GEMM 突发读取 $W_e$</td><td>HBM 带宽瞬时饱和，解码尾延迟抬升，SLO 抖动</td></tr><tr><td>低秩因子常驻挤占显存</td><td>专家数×秩×分片常驻，与 KV cache 争用</td><td>批大小被迫下调，吞吐下降，抵消带宽收益</td></tr><tr><td>EP 度过大</td><td>All-to-All 跳数增加，低秩中间激活跨多级交换</td><td>NVLink 与 NVSwitch 域内争用，同步开销上升</td></tr><tr><td>秩小于切分粒度</td><td>TP/EP 分片后 MMA 形状不足</td><td>tcgen05 利用率下降，算力换带宽不划算</td></tr></tbody></table>\n\n<p>具体例子：GB200 NVL72 单域内 EP 度拉到较大值时，一个 token 的低秩中间激活需经多跳 All-to-All 抵达目标专家所在卡，若此时 $\\rho$ 因长尾专家命中而抬升，回退路径的完整权重读取与 All-to-All 在同一时间窗叠加，NVLink 与 HBM 两条链路同时吃紧，尾延迟由两者中较慢者决定。此时调度器的正确动作不是单纯调大阈值压回退率——那会牺牲近似精度——而是先按专家命中分布重排 EP 拓扑，把高频回退专家聚到同一 NVLink 域内，缩短回退路径的跨卡距离，再联动 NIXL 传输层把低秩因子预取与 KV cache 搬运错峰。监控须同时盯回退率、专家命中分布、HBM 带宽占用与 All-to-All 排队时延四项，任一项越界即触发拓扑或阈值调整，而不是等尾延迟已经破线再补救。</p>\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-36\">三十六 · 精度塌陷：从残差判定到回退路径的失效链</h3>\n<p>低秩补偿推理的精度风险不在低秩因子本身，而在残差判定与回退路径的耦合方式。判定式 $\\mathbb{1}\\{\\|\\mathrm{res}_e\\|&gt;\\tau\\}$ 是一个逐 token、逐专家的硬门限：一旦残差被低估，该 token 就永久停留在低秩近似结果上，误差直接进入后续层并被路由放大。工程上最典型的塌陷形态是“长尾专家漂移”——高频专家被充分校准、低秩因子拟合良好，而低频专家在批内只被少数 token 命中，其 $U_e V_e^{\\top}$ 与 $W_e$ 的偏差在单次前向中不显著，但在长上下文或连续批处理中沿层累积，表现为输出重复、格式崩坏或指令遵循退化，而非 perplexity 突变。</p>\n<p>诊断这类问题的关键是区分“判定失效”与“因子失效”。判定失效指 $\\|\\mathrm{res}_e\\|$ 的计算本身被近似或省略（例如用低秩中间激活的范数代替真实残差），此时回退率监控看起来正常，但精度已静默降级；因子失效指残差计算正确、阈值合理，但低秩因子对特定专家覆盖不足。前者需要在前向图中保留残差计算的独立路径，后者需要按专家索引记录命中与回退的联合分布。代价上，残差判定本身是一次额外的范数计算与比较，在分组 GEMM 之后插入，增加少量分支开销，但真正的代价是它把计算图切成低秩路径与回退路径两条，调度器必须按 token 标记分流，批内出现“部分 token 走补偿 GEMM”的不规则形状，降低 GEMM 的规整度。</p>\n<p>具体例子：某层 top-k=2 的路由把一批 token 分散到 64 个专家，其中 8 个专家在批内各只命中 1–2 个 token。若这 8 个专家的低秩因子秩偏小，其残差在范数上恰好落在 $\\tau$ 附近，判定结果在批与批之间抖动，同一请求在不同批组合下得到不同精度。定位方法是按专家维度聚合回退率与残差分布，而不是只看全局平均回退率——全局指标会被高频专家稀释。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-37\">三十七 · OOM：常驻低秩因子与 KV cache 的显存争用</h3>\n<p>低秩因子按专家索引常驻或分片存放，这笔显存开销与 KV cache、批大小共同竞争同一预算。专家数 $E$、秩 $r$、隐藏维度 $d$ 决定单专家因子占用约为 $2 \\cdot d \\cdot r$ 个元素（$U_e$ 与 $V_e$ 各一），乘以 $E$ 后是固定常驻项；KV cache 则随批内 token 数与上下文长度线性增长。OOM 的典型触发点不是稳态，而是预填阶段的批膨胀：调度器按吞吐目标放大批大小，KV cache 瞬时抬升，与常驻因子叠加越过显存上限。专家并行下情况更复杂——低秩因子与专家权重同拓扑切分，每卡只持有部分专家的因子，但 All-to-All 的低秩中间激活缓冲区仍需按最坏情况预留，若按平均激活量分配，回退率升高时缓冲区溢出。</p>\n<div class=\"formula\">$$M_{\\text{resident}} \\approx E \\cdot 2dr \\cdot b + B \\cdot L \\cdot H_{\\text{kv}} + M_{\\text{comm}}$$</div>\n<p>其中 $b$ 为每元素字节数（受 NVFP4/FP8 位宽影响），$B$ 为批内 token 数，$L$ 为上下文长度，$H_{\\text{kv}}$ 为每 token KV 开销，$M_{\\text{comm}}$ 为通信缓冲。这个式子说明：降低秩能直接释放常驻显存，但会推高回退率，进而抬升 $M_{\\text{comm}}$ 与带宽尖峰——显存与带宽的权衡不是独立的。工程判断上，容量规划应把常驻因子视为硬预留，把 KV cache 视为弹性项，批大小由两者之差反推，而不是先定批大小再塞因子。</p>\n<p>具体例子：GB200 NVL72 拓扑下专家分片到多卡，每卡专家数减少使常驻因子占用下降，但跨卡 All-to-All 的低秩激活缓冲随并行度上升；若并行度提高而缓冲未同步扩容，回退率一旦超过设计点，OOM 会以通信缓冲分配失败的形式出现，而非 KV cache 溢出，误导排查方向。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-38\">三十八 · 批抖动与尾延迟：回退率作为批内随机变量</h3>\n<p>连续批处理下，每个批次的回退 token 数是随机变量，取决于该批 token 的路由结果与残差分布。回退触发的完整专家权重读取是带宽尖峰事件：同一批内若多个 token 回退到同一专家，分组 GEMM 需要读取该专家全量权重；若分散到多个专家，则读取量按专家数增长。这使批的带宽需求不再由批大小单调决定，而由“批内回退 token 的专家分布”决定。尾延迟的来源正是这种分布的重尾：多数批次回退率低、延迟平稳，少数批次因专家命中集中而带宽骤增，P99 延迟被拉高。</p>\n<p>调度器可用的手段是限制批内回退比例上限，超出则拆分批次或推迟部分 token 到下一批。代价是吞吐下降与排队延迟上升，且拆分本身改变批组合，可能再次触发不同的路由分布，形成抖动循环。监控上必须把回退率与专家命中分布作为批级指标记录，而非请求级平均——请求级平均会掩盖批级尖峰。具体例子：解码阶段每步只处理少量 token，单 token 回退即占该步带宽的显著比例，尾延迟对单次回退极其敏感；此时应优先保证低秩路径的覆盖率，而不是追求回退率的最小化。</p>\n<p>另一个抖动源是阈值 $\\tau$ 的自适应调整：若系统按近期回退率动态调 $\\tau$，调参窗口与批周期不同步会造成正反馈——回退率升高触发阈值放宽，放宽后近似误差上升、更多 token 被判回退，形成震荡。工程上应把 $\\tau$ 的调整放在批间而非批内，并设置调整幅度上限。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-39\">三十九 · 静默降级：监控指标的设计与陷阱</h3>\n<p>静默降级指系统吞吐与延迟指标正常、无报错，但输出质量已退化。低秩补偿路径的静默降级有三个来源：残差判定被旁路、低秩因子版本与专家权重不对齐、量化位宽与因子精度不匹配。三者都不会触发 OOM 或超时，只会让回退率“看起来健康”。监控设计必须包含与质量弱相关的代理指标：按专家的回退率分布（而非全局均值）、低秩路径输出与回退路径输出的范数比、专家命中分布的熵。范数比异常升高说明低秩近似与完整权重的贡献偏离，是因子失效的早期信号。</p>\n<p>指标采集本身有代价：逐 token 记录残差范数与专家索引会增加写带宽与显存占用，在高吞吐下不可全量采样。可行做法是按批采样固定比例的 token，并对所有回退事件做完整记录——回退是稀有事件，全记录成本可控，而低秩路径的采样足以估计分布。具体例子：若某专家的回退率从设计点附近突然归零，同时其命中数不变，应怀疑该专家的残差判定被短路（例如因子读取越界返回零），而非精度变好；此时范数比指标会同步异常。</p>\n<p>静默降级的另一形态是量化共存问题：低秩因子与专家权重采用不同位宽时，低秩路径的误差与回退路径的误差量级不同，残差阈值 $\\tau$ 的语义在两个精度域之间漂移。材料未给出具体位宽与校准方法，工程上应以同一精度域内标定 $\\tau$，跨精度域部署时重新标定，而不是沿用原阈值。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-40\">四十 · 定位与回滚：从指标到动作的路径</h3>\n<p>定位的顺序应由外向内：先看批级回退率与尾延迟是否同步抬升（指向带宽尖峰），再看专家维度回退分布是否集中（指向长尾专家因子失效），最后看范数比与残差分布是否漂移（指向判定或因子问题）。三者组合能区分“负载形态变化”与“系统退化”：前者回退率上升但范数比稳定，后者范数比同步异常。定位到专家维度后，可对该专家临时强制回退（把 $\\tau$ 对该专家置零），观察精度是否恢复，以此确认是因子问题而非判定问题。</p>\n<p>回滚的最小单元应是低秩因子而非整个模型：按专家索引回退到完整权重读取，等价于把该专家的 $\\tau$ 置零，带宽代价局限于该专家的命中量。整模型回滚（关闭低秩补偿分支）代价最大但最确定，适用于因子版本错配或量化域漂移这类全局问题。回滚动作需要与调度器联动：关闭补偿分支后批的带宽需求整体上升，批大小与并行拓扑需同步收缩，否则回滚本身触发 OOM 或尾延迟恶化。</p>\n<p>具体机制上，可维护一份按专家的“健康标记”，由回退率分布与范数比联合判定，标记为不健康的专家在路由后被强制走完整权重路径，其余专家继续低秩路径。这把回滚从全局开关变成逐专家开关，代价是计算图进一步不规则化，分组 GEMM 需处理混合路径。工程判断：在专家数多、长尾明显的部署中，逐专家回滚的带宽代价远小于整模型回滚，但调度复杂度上升；在专家数少、命中集中的场景，整模型回滚更易验证。无论哪种，回滚触发条件必须与监控指标绑定并留出人工确认窗口，避免自动回滚在负载抖动下反复切换。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-41\">四十一 · 失败模式与容量规划的联动</h3>\n<p>上述失败模式并非独立：精度塌陷推高回退率，回退率推高带宽尖峰与尾延迟，尾延迟迫使调度器收缩批大小，批大小收缩又改变专家命中分布、加剧长尾专家的因子失效。这是一个闭环，容量规划必须把回退率作为一等变量而非事后指标。规划式可写为：给定 SLO 的尾延迟上限，反推允许的批内回退比例上限，再由该上限与专家命中分布估计所需带宽与通信缓冲，最后校验常驻因子与 KV cache 的显存可行性。任何一环不满足，调整顺序应是先降秩释放显存、再调 $\\tau$ 控制回退率、最后调并行拓扑分摊带宽，而不是先扩批。</p>\n<p>具体例子：B300 档位下若 NVFP4 权重使单专家读取带宽下降，回退的绝对代价变小，允许的回退比例上限可放宽，尾延迟敏感性下降；反之 FP8 部署下回退代价更高，阈值应更保守。材料未给出具体位宽与阈值数字，工程上应以实测的回退代价曲线标定，而非套用固定比例。监控指标、回滚开关与容量参数应放在同一配置面内联动，避免监控发现退化而容量参数仍按旧假设运行——这是静默降级最常见的组织性成因。</p>\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-42\">四十二 · 基准口径的骨架：先钉死模型与硬件档位</h3>\n<p>读这篇低秩补偿 MoE 推理工作，第一件要做的不是看它快多少，而是确认它到底在什么口径下被度量。材料给出的硬件档位是 B200/B300/GB200 NVL72，但明确没有给出具体部署档位与拓扑数字；模型侧同样只给出机制描述，没有指定参数量、专家数、top-k 取值。这意味着任何跨条目横向比较都缺少共同的锚点。工程上可行的做法是把口径拆成可复现的三层：模型层记录专家总数、激活专家数 top-k、隐藏维与专家中间维、是否共享专家；硬件层记录单卡还是 NVL72 机柜级、NVLink 域大小、SM 数、NVFP4/FP8 峰值；拓扑层记录专家并行度、每卡驻留专家数、All-to-All 走的是域内 NVLink 5 还是跨域。缺任何一层，吞吐数字就失去意义。举例来说，同一份低秩补偿代码在 B200 单卡上跑出的 tokens/s，与在 GB200 NVL72 上以专家并行度 8 跑出的 tokens/s，分母完全不同——前者没有 All-to-All，后者把低秩中间激活跨卡交换的代价算进了端到端延迟。论文材料没有给出这些数字，因此本部分的读法是：把每个报告值绑定到它自己的口径三元组，拒绝脱离三元组的“提升百分比”。</p>\n<p>硬件档位还决定精度路径的可比性。Blackwell 的 NVFP4/FP8 与 tcgen05 加速是档位自带能力，材料说明低秩因子可与 NVFP4/FP8 权重共存，但未给出具体位宽与校准方法。于是两个实验若一个用 FP8 专家权重、一个用 NVFP4，即便回退率相同，专家权重读取的字节数也不同，带宽节省幅度不可直接相减。口径表里必须单列“权重精度”“低秩因子精度”“KV cache 精度”三栏，任何一项不同即判定为不可比。</p>\n<div class=\"formula\">$$\\text{可比性} = \\mathbb{1}\\{\\text{模型同构}\\}\\cdot\\mathbb{1}\\{\\text{硬件档位同档}\\}\\cdot\\mathbb{1}\\{\\text{并行拓扑同构}\\}\\cdot\\mathbb{1}\\{\\text{精度路径同配}\\}$$</div>\n<p>这个指示函数不是形式主义：四项里任意一项为假，两个吞吐数字的差值就混入了非方法本身的贡献。工程判断是，先把不可比的对子标出来，剩下的才进入深读。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-43\">四十三 · batch 与并发：两种分母不能混用</h3>\n<p>低秩补偿的收益高度依赖批内 token 的专家命中分布。材料给出的调度路径是：预填阶段按 token 长度分桶，批大小受显存带宽与回退率约束；解码阶段按 SLO 调整批大小与回退比例。这里存在两个不同的分母。其一是“静态 batch”：一次前向里固定塞进 N 个 token，吞吐按 N 除以单步时间算；其二是“并发会话”：连续批处理下，batch 组成随请求到达与完成动态变化，吞吐按单位时间完成的请求数或输出 token 数算。两者不可互换，因为动态批里每个 token 的专家命中分布随会话演进而漂移，回退率是时间的函数，而静态 batch 的回退率在单步内是常数。</p>\n<p>具体机制上，分组 GEMM 先聚合低秩贡献，再对残差超阈值的 token 触发完整专家权重读取。批越大，单次分组 GEMM 覆盖的 token 越多，低秩因子的读取越能被摊薄——这是带宽效率的来源。但批越大，回退 token 的绝对数量也可能上升，一旦触发完整专家权重读取，带宽尖峰与低秩路径的平缓读取叠加，尾延迟被拉长。材料明确指出尾延迟敏感场景需限制回退比例，否则 SLO 稳定性受批调度与专家命中分布影响。因此报告吞吐时必须同时给出 batch 上限策略：是固定最大 batch，还是按回退率反馈动态收缩。前者吞吐高但尾延迟不可控，后者 SLO 稳但吞吐分母被压低。两种策略下的 tokens/s 不可比。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>静态 batch</th><th>连续批处理</th></tr></thead><tbody><tr><td>吞吐分母</td><td>单步 token 数 / 单步时间</td><td>单位时间完成 token 数</td></tr><tr><td>回退率性质</td><td>单步内常数</td><td>随会话演进漂移</td></tr><tr><td>尾延迟来源</td><td>批内最慢 token 的回退</td><td>回退尖峰与新请求插入的叠加</td></tr><tr><td>可比性</td><td>仅与同 batch 策略对子比</td><td>仅与同调度器配置对子比</td></tr></tbody></table>\n<p>举例：一个变长请求负载，预填按长度分桶后，长桶的 token 更容易命中长尾专家，回退率偏高；短桶回退率低。若报告只给总吞吐而不给桶分布，读者无法判断带宽节省来自低秩路径还是来自短桶偏多。工程上应把回退率按桶与按专家命中分布拆开记录，这是材料中“记录回退率与专家命中分布，供容量规划”的直接落点。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-44\">四十四 · 指标族：TTFT、TPOT、吞吐、显存、功耗各自的口径陷阱</h3>\n<p>TTFT 在低秩补偿路径上被两段放大：预填阶段的路由 logits 计算与低秩因子读取，以及回退 token 触发的完整专家权重读取。材料说明预填阶段计算路由并选出 top-k，随后低秩分支读取因子做分组 GEMM。TTFT 的口径必须声明是否包含回退补偿 GEMM——若包含，TTFT 是回退率的函数；若不包含，TTFT 只反映低秩路径，是乐观值。TPOT 同理：解码阶段复用常驻低秩因子与 KV cache，单 token 的 TPOT 取决于该 token 是否回退，而回退判定在解码步内完成，因此 TPOT 的分布是双峰的，均值会掩盖尾部的带宽尖峰。报告 TPOT 时应给 p50 与 p99，并注明 p99 是否由回退触发。</p>\n<p>吞吐的口径陷阱在于是否把回退补偿 GEMM 的算力计入。低秩路径的 FLOPs 远小于全量专家矩阵乘法，但回退路径的补偿 GEMM 与全量读取等价。若吞吐按“有效输出 token 数 / 总时间”算，回退越多吞吐越低，这与带宽节省的直觉相反——因为回退把省下的带宽又花回去了。显存口径要分常驻与峰值：低秩因子按专家索引常驻或分片存放，专家数越多、秩越大，常驻占用越高，需与 KV cache 和批大小共同规划显存预算；峰值则出现在回退集中触发时完整专家权重的临时驻留。材料未给出秩与专家数数字，因此显存口径只能定性描述为“常驻低秩因子与 KV cache 争用显存”。</p>\n<div class=\"formula\">$$\\text{TPOT}_{p99}\\ \\text{由回退触发} \\iff \\text{该步回退 token 数} &gt; \\text{带宽余量对应的阈值}$$</div>\n<p>功耗口径在 Blackwell 档位上尤其敏感：NVFP4/FP8 路径的能效与全精度路径不同，低秩因子若以低精度存放，读取功耗下降，但回退路径的全量读取会把功耗拉回高位。材料没有给出功耗数字，工程上只能把功耗作为回退率的单调函数定性记录，不能与不同精度配置的对子相减。举例：一个以 FP8 权重加低秩因子 FP8 的配置，与一个 NVFP4 权重加低秩因子 FP8 的配置，即便回退率相同，每 token 的专家权重字节数不同，功耗与带宽节省都不可直接比较。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-45\">四十五 · 数字怎么读：把“提升”拆成可归因的因子</h3>\n<p>材料明确没有给出可核验的实验数字，并声明收益取决于回退率与低秩秩的取值：回退率越低、秩越小，专家权重带宽节省越明显，但近似误差可能上升。这句话本身就是读数字的规则。任何报告的吞吐提升必须能被分解为三个因子：低秩路径替代全量读取带来的带宽下降、回退比例带来的带宽回吐、以及分组 GEMM 聚合低秩贡献带来的算力结构变化。三者中只有第一个是方法的核心贡献，第二个是代价，第三个是中性或正负未知。若一个提升数字没有附带回退率，它无法归因——因为同样的提升可以来自回退率极低（方法有效）或来自批内短桶偏多（负载偏差）。</p>\n<p>具体机制上，残差阈值 τ 是带宽与精度的显式旋钮：阈值越低回退越多、带宽节省越少但近似误差越小。读数字时应把 τ 与回退率成对记录，因为 τ 是配置，回退率是结果，二者共同决定带宽曲线上的工作点。材料未给出具体阈值与回退率数字，因此任何“提升 X%”若不带 τ 与回退率，只能视为该工作点上的单点观测，不能外推到其他 τ。举例：若某报告称吞吐提升，但未说明 τ，读者无法判断这是低秩路径的功劳还是 τ 设得极高导致几乎不回退、近似误差被放任的结果——后者在精度敏感场景不可接受。</p>\n<table class=\"mini\"><thead><tr><th>报告项</th><th>可归因条件</th><th>不可比情形</th></tr></thead><tbody><tr><td>吞吐提升</td><td>附回退率、τ、batch 策略</td><td>缺回退率或 τ 不同</td></tr><tr><td>带宽节省</td><td>附权重精度与低秩因子精度</td><td>精度配置不同</td></tr><tr><td>TTFT 下降</td><td>声明是否含回退补偿 GEMM</td><td>口径含/不含混用</td></tr><tr><td>显存占用</td><td>分常驻与峰值，附专家数与秩</td><td>秩或专家数不同</td></tr></tbody></table>\n<p>另一个不可比来源是专家并行拓扑。材料说明低秩因子可与专家权重同拓扑切分，All-to-All 只交换低秩中间激活与门控系数，跨卡激活体积小于全量激活交换，但同步与切分带来额外通信代价。拓扑不同，All-to-All 的体积与同步次数不同，端到端延迟的可比性被破坏。工程判断是：只有当两个对子的专家并行度、每卡专家数、NVLink 域范围一致时，通信代价才可相消，否则吞吐差值里混入了拓扑贡献。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-46\">四十六 · 不可比清单与工程判断</h3>\n<p>把上述口径收敛成一份不可比清单，是本部分的落点。清单条目包括：模型专家数与 top-k 不同；硬件档位跨 B200/B300/GB200 NVL72 且未声明拓扑；batch 策略一为静态一为连续批处理；权重或低秩因子精度配置不同；τ 与回退率未成对给出；TTFT/TPOT 口径是否含回退补偿 GEMM 未声明；显存口径未分常驻与峰值；专家并行度与 NVLink 域范围不同。任意一条命中，两个数字的差值就不能归因于低秩补偿方法本身。材料中“材料未给出具体秩、阈值与量化位宽数字”这一声明，意味着该工作的所有性能主张在当前材料下只能做机制级判断，不能做定量横比。</p>\n<p>工程判断落在监控与容量规划上：监控指标应包含回退率、专家命中分布、带宽占用与尾延迟；回退率升高会侵蚀带宽收益，需联动调整阈值或并行拓扑。这句话给出了读数字之后的动作——不是追求单点最高吞吐，而是把 τ 与批大小作为闭环控制量，在 SLO 约束下把回退率压在带宽余量之内。具体机制上，调度器按 token 标记分流低秩路径与回退路径，增加少量判定与分支开销；这个开销在批大时被摊薄，在批小时占比上升，因此小 batch 场景的吞吐数字天然不利于该方法，不能与大批场景直接比较。举例：一个尾延迟敏感的在线服务，若把 τ 调低以压回退率，带宽节省下降但 p99 TPOT 稳定；若把 τ 调高，吞吐上升但回退尖峰可能击穿 SLO。两个工作点的吞吐数字不可比，因为它们对应不同的 SLO 约束。</p>\n<p>最后落在具体机制上：低秩因子常驻显存与 KV cache 争用是容量规划的死结，专家数越多、秩越大，常驻占用越高，批大小被迫收缩，吞吐分母随之下降。读任何吞吐数字时，先问它的批大小是否被常驻显存压过——若是，该数字反映的是显存容量而非带宽效率。这条判断比任何百分比都更能决定该方法在给定 Blackwell 档位与拓扑下是否值得部署。</p>\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-47\">四十七 · 迁移到非 MoE 结构：低秩补偿失去路由这个抓手</h3>\n<p>这套方案的全部杠杆都挂在路由之后：路由先把 token 收敛到 top-k 专家，低秩因子才有一个确定的专家索引可以查，残差判定才有“近似的是哪一块权重”这个明确对象。迁到稠密模型时，这个抓手消失。稠密 FFN 每个 token 都要过同一组权重，没有稀疏命中，低秩近似要么退化为对整个 FFN 做低秩分解（那就不是“补偿”，而是模型压缩，误差会沿层累积且没有回退对象可选），要么变成对激活做低秩投影，与专家权重读取带宽无关。判断很直接：稠密模型上这套机制不适用，应当改用权重-only 量化或 KV 侧优化，而不是硬套残差回退。</p>\n<p>迁到细粒度专家（专家数很多、单个专家很窄，如 DeepSeekMoE 式切分）时，机制仍然成立，但代价结构变了。专家数 $E$ 增大时低秩因子常驻显存按 $E \\cdot r \\cdot (d_{in}+d_{out})$ 线性增长，而单专家全量权重按 $E \\cdot d_{in} \\cdot d_{out}$ 增长；低秩的相对节省比约为 $r/(d_{in}d_{out}/(d_{in}+d_{out}))$，即秩相对于调和维度的比例。专家越窄，这个比值越不友好——窄专家的 $d_{in},d_{out}$ 小，低秩因子占全量权重的比例上升，常驻显存收益被侵蚀。所以细粒度 MoE 上要迁移，第一件事是重新核算“低秩因子常驻 + KV cache + 批大小”三者争用的显存预算，而不是照搬原拓扑。</p>\n<p>迁到共享专家 + 路由专家的混合结构时，共享专家不该走低秩路径：它每个 token 必过，读取量恒定且已被批内复用摊薄，对它做低秩近似只会引入误差而不省带宽。低秩补偿应只作用于路由专家，且优先作用于命中率高、权重块大的那批专家——命中率高的专家回退概率也高，需要单独评估其回退率是否把节省吃掉。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-48\">四十八 · 领域迁移：长上下文、多模态与低延迟场景的边界</h3>\n<p>长上下文预填是这套方法收益最明显的场景，也是最容易失守的场景。预填阶段 token 量大、路由分散，低秩路径聚合能显著压低每 token 的专家权重读取；但预填的批内 token 分布若高度偏斜（少数专家吃掉大部分 token），这些热专家的回退会集中触发，形成带宽尖峰。设批内 token 数为 $B$、专家 $e$ 的命中数为 $n_e$、回退率为 $\\rho_e$，则该专家触发的全量读取量正比于 $\\rho_e n_e d_{in}d_{out}$，而低秩路径读取量为 $n_e r(d_{in}+d_{out})$。带宽节省能否成立，取决于 $\\sum_e \\rho_e n_e$ 相对 $\\sum_e n_e$ 的比例，也就是加权回退率而非全局平均回退率。工程判断：按专家维度监控 $\\rho_e$，对 $\\rho_e$ 高的专家单独调低阈值或干脆不走低秩路径，比调全局 $\\tau$ 更有效。</p>\n<p>解码阶段是另一回事。解码每步 token 少，专家权重读取的绝对量小，低秩因子常驻显存反而成了主要成本；此时收益主要来自 All-to-All 激活体积缩小，而非权重带宽。低延迟、小批量的在线服务（尾延迟敏感、SLO 以 P99 计）要谨慎：残差判定本身要算 $\\|res_e\\|$，这是一次额外的低秩 GEMM 加范数计算，在 decode 的小算子里占比不低；回退分支还引入控制流分歧，分组 GEMM 的 token 标记分流会让 kernel 的有效占用率下降。判断：decode 主导、批大小上不去的场景，这套方法的净收益不确定，应先做残差判定开销的实测再决定是否启用。</p>\n<p>多模态与长序列检索类负载的 token 分布与文本不同，视觉 token 往往集中在少数专家，回退集中度更高；这类负载迁移时阈值应偏保守（更高 $\\tau$、更少回退），把带宽节省让位给尾延迟稳定。反过来，离线批处理、吞吐优先的负载可以把 $\\tau$ 调低、容忍更多回退，用带宽尖峰换平均吞吐。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-49\">四十九 · 规模上限：专家并行度、All-to-All 与常驻显存的三角约束</h3>\n<p>规模上限不在单卡，而在专家并行拓扑与 All-to-All 的交互。低秩路径把跨卡交换的体积从全量激活降到低秩中间激活加门控系数，交换量约按 $r/(d_{out})$ 比例缩小；但交换的“次数”没变，每个 token 仍要按 top-k 做 dispatch 与 combine。当专家并行度 $P$ 增大、单卡专家数减少时，All-to-All 的固定开销（消息头、同步、NCCL 通道建立）在总延迟中的占比上升，低秩带来的体积节省被摊薄。存在一个并行度拐点：超过它之后，继续加卡换来的带宽节省小于通信固定开销的增长。判断依据是每步 All-to-All 的有效载荷字节数与固定开销字节数的比值，而不是卡数本身。</p>\n<p>常驻显存给出第二个上限。低秩因子按专家切分常驻，单卡占用为 $E_{local}\\cdot r\\cdot(d_{in}+d_{out})\\cdot b$（$b$ 为每元素字节数，NVFP4 下更小）。它与 KV cache 争用同一块 HBM：批大小受 KV 约束时，低秩因子占用直接压缩可用批空间，进而压低吞吐。这里有一个自洽性条件——低秩带来的带宽节省必须大到足以抵消因批变小而损失的吞吐，否则净收益为负。工程上应把“低秩因子显存占比”作为容量规划的显式输入，而不是事后补算。</p>\n<p>第三个上限是回退率的可控性。回退率随负载漂移，长尾专家上的近似误差会累积，判定过粗时回退不是节省而是尖峰。系统层面需要一个闭环：监控回退率与尾延迟，联动调整 $\\tau$ 或并行拓扑。这要求调度器能按 token 标记分流并快速重配，否则阈值调了但批已经发出，尖峰照旧。规模越大、专家命中分布越不稳定，这个闭环的响应速度越是瓶颈。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-50\">五十 · 量化共存与数值边界：低秩因子与 NVFP4/FP8 的相互影响</h3>\n<p>低秩因子与专家权重可以各自量化，但两者的量化误差不是独立的：低秩路径的近似误差与量化误差叠加后才进入残差判定，残差阈值 $\\tau$ 实际约束的是“低秩截断误差 + 量化误差”的合成。若低秩因子用更低比特（如 NVFP4）存储以省常驻显存，其量化误差会抬高残差，导致回退率上升——省了显存却丢了带宽。这是一个显式的权衡：低秩因子的位宽选择必须和 $\\tau$ 联合标定，不能分开调。材料未给出具体位宽与校准方法，迁移时必须自行做这个联合标定。</p>\n<p>另一个数值边界在补偿项。回退时计算的是 $W_e x - U_e V_e^{\\top}x$，两项量级可能相差很大，若 $U_eV_e^{\\top}x$ 已接近 $W_e x$，补偿项是小数相减，在 FP8 下有效位损失明显；此时用 FP8 做补偿 GEMM 可能引入比低秩截断更大的误差。判断：补偿路径宜用较高精度（BF16 或 FP8 带缩放），低秩聚合路径可用 NVFP4/FP8；两条路径的精度配置不应统一。</p>\n<p>量化还改变带宽账本。专家权重用 NVFP4 存储时，全量读取的字节数已降到 FP16 的四分之一左右，低秩路径相对全量路径的带宽节省比例随之缩小——低秩因子若也是 NVFP4，节省比仍是秩与维度的比值，但绝对节省量变小。这意味着在已经重度量化的部署里，低秩补偿的边际收益下降，应优先评估是否值得引入残差判定与回退分支的复杂度。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-51\">五十一 · 不适用清单与迁移检查项</h3>\n<p>明确不适用或需重估的情形：稠密模型（无路由抓手）；专家极窄且专家数极大的切分（常驻显存收益被侵蚀）；decode 主导、批大小受限的低延迟在线服务（判定开销与分支分歧占比高）；已重度 NVFP4 量化且带宽不再是最紧约束的部署（边际收益下降）；专家命中分布剧烈漂移且调度器无法快速重配阈值的场景（回退尖峰不可控）。</p>\n<p>迁移时的检查项应落到可核验的量上，而不是口号：</p>\n<ul>\n<li>加权回退率 $\\sum_e \\rho_e n_e / \\sum_e n_e$ 是否在 SLO 允许的尾延迟预算内，按专家维度而非全局平均监控。</li>\n<li>低秩因子常驻显存占 HBM 的比例，与 KV cache、批大小联立求解后的净吞吐是否为正。</li>\n<li>All-to-All 有效载荷字节数与固定开销字节数的比值，判断并行度是否已过拐点。</li>\n<li>低秩因子位宽与 $\\tau$ 的联合标定是否完成，残差判定是否计入量化误差。</li>\n<li>补偿路径的精度配置是否独立于低秩聚合路径，避免小数相减的有效位损失。</li>\n<li>调度器能否按 token 标记分流并在阈值调整后快速生效，闭环响应时间是否短于负载漂移周期。</li>\n</ul>\n<p>最后落在机制上：这套方法的可迁移性取决于“路由给出的稀疏命中”是否真实存在且稳定，以及“低秩因子常驻显存”是否能在与 KV cache 的争用中留下足够批空间。两个条件任一不成立，回退式压缩就从带宽优化退化为复杂度负担——迁移判断应先测这两个量，再谈阈值与秩。</p>\n\n<h3 id=\"paper-bandwidth-efficient-adaptive-mixture-2025-sec-52\">五十二 · 迁移边界：什么模型吃得下这套方案，什么拓扑会把它吃掉</h3>\n\n<p>低秩补偿的收益结构决定了它的迁移性不是“通用加速器”，而是一组前置条件。第一，专家权重必须存在可压缩的谱冗余：若某模型的专家矩阵本身接近满秩、或专家间差异极大导致单专家低秩近似误差高，则回退率被推高，带宽节省被残差判定与补偿 GEMM 抵消。第二，路由必须呈现可预测的专家命中分布：命中集中在少数专家时，低秩因子常驻显存按专家索引切分尚可控；命中长尾分散时，常驻因子总量随激活专家数线性膨胀，与 KV cache 争用显存预算。第三，专家并行拓扑必须允许低秩因子与专家权重同切分——若框架把专家权重按张量并行切分而非专家并行切分，低秩因子无法复用同一通信域，All-to-All 只交换低秩中间激活的设计前提失效。判断标准应落在回退率与常驻显存两项可测量上，而不是“是否 MoE”。</p>\n\n<p>规模上限由两个代价曲线的交点给出。设专家数 $E$、秩 $r$、隐藏维 $d$、每 token 激活专家数 $k$，低秩路径每 token 权重读取量约为 $k\\cdot 2rd$（两个因子），全量路径为 $k\\cdot d^2$；回退率 $p$ 下有效读取量为</p>\n<div class=\"formula\">$$B_{\\text{eff}} \\approx k\\,d\\left(2r + p\\,(d-2r)\\right),\\qquad M_{\\text{resident}} \\approx E\\cdot 2rd\\cdot b$$</div>\n<p>其中 $b$ 为每元素字节数。带宽节省要求 $2r + p(d-2r) &lt; d$，即 $p &lt; 1 - 2r/d$；当 $r$ 接近 $d/2$ 时该不等式几乎不给回退留余量，方案退化为“多读一份因子再读全量”。常驻显存 $M_{\\text{resident}}$ 则随 $E$ 线性增长，在 GB200 NVL72 这类多专家、大并发的部署里，它与 KV cache、批大小三者共享同一显存预算。规模上限因此不是固定专家数，而是“$E\\cdot r$ 乘积与可用显存减去 KV cache 后的余量之比”——专家数翻倍或秩翻倍，常驻占用同步翻倍，而带宽收益只随 $r/d$ 缓慢改善，这是该方案最陡的失效方向。</p>\n\n<p>不适用场景要具体点名。其一，专家数很少（如 8 专家级）且单专家权重不大的模型：全量读取本就未构成带宽瓶颈，插入低秩分支只增加判定与分支开销，分组 GEMM 被拆成两条路径反而降低 SM 利用率。其二，尾延迟硬约束的在线服务：回退触发的完整专家权重读取是带宽尖峰，其到达时刻由 token 内容决定而非调度器决定，批内只要少量 token 回退即可拉高整批尾延迟；此时阈值 $\\tau$ 被迫调高，近似误差上升，方案退化为“低秩近似 + 高误差”，不如直接做量化或 KV 压缩。其三，专家并行度低、跨卡激活交换本就不是瓶颈的拓扑：All-to-All 体积缩减带来的收益被低秩因子的切分同步成本吃掉。其四，量化已把权重压到 NVFP4 的场景：权重字节数下降后，全量读取的带宽代价本身缩小，低秩路径的相对优势收窄，而低秩因子若也用 NVFP4 则近似误差与量化误差叠加，残差判定更易触发回退。</p>\n\n<p>迁移到新领域时，要改的不是公式而是三个旋钮的联动标定。残差阈值 $\\tau$ 必须按目标 SLO 的尾延迟预算反推：先测回退率对尾延迟的敏感度，再定 $\\tau$，而不是先定 $\\tau$ 再看延迟。秩 $r$ 要按“常驻显存余量 ÷ 专家数”反推上限，再在此上限内选使回退率可接受的最小秩——秩不是越大越好，$r$ 增大同时抬高常驻占用与低秩 GEMM 计算量。并行拓扑要确认低秩因子与专家权重落在同一专家并行切分下，否则 All-to-All 交换的低秩中间激活需额外重排。监控必须把回退率、专家命中分布、带宽占用与尾延迟绑定为联动指标：回退率升高时先调 $\\tau$ 还是先改拓扑，取决于命中分布是集中还是长尾——集中命中说明个别专家近似差，应针对该专家单独提高秩；长尾命中说明阈值判定过粗，应改判定粒度而非全局调 $\\tau$。这套方案的工程判断只有一句：它省的是“按专家全量读取”的带宽，代价是常驻显存与不可预测的回退尖峰；当这两项代价中任一项逼近预算边界时，迁移即失效，应退回量化加 KV 压缩的常规路径。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Bandwidth-Efficient </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Adaptive Mixture-of…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Bandwidth-Efficient Ada… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出具体基线名称</td></tr><tr><td>主要结果</td><td>材料未给出可核验的实验数字；从机制上看，收益取决于回退率与低秩秩的取值，回…</td></tr><tr><td>消融</td><td>材料未给出消融实验；可关注的消融维度为低秩秩大小、残差阈值 $\\tau$、…</td></tr><tr><td>局限</td><td>材料未给出实验限制与失败模式数字；可推断的代价包括低秩因子常驻显存、残差判…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-bandwidth-efficient-adaptive-mixture-2025 · 共 9 个片段</p>\n";break;}}})();
